INSERT INTO `douyin_aweme_comment` VALUES (9, '7618128613921883173', 'MS4wLjABAAAAg2c5ZGqyMOsU_RHIv47a6jSGy8D84iGVx4e9joxSeoUe_T7cYfVt4uO9bu3lH_of', '28927275543', '28927275543', '旺椰椰', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oI3te3CL0EeAAAE7wEeiEDBiI3BAUZAFlwvqZX.jpeg?from=2064092626', NULL, '云南', 1780981788796, 1780981788794, 7649181979460928293, 7648947265968639247, '这次高考题全部出乎所有人的意料之中，让寒窗苦读十二年的孩子们心灰意冷，如果想改变以后孩子们的学习方法，老师也要更新了，不然的话怎么跟上时代的变化呢？', 1780963966, '1', '0', '53', '');
INSERT INTO `douyin_aweme_comment` VALUES (10, '87372626542', 'MS4wLjABAAAA8UE9maO6XNAF7QMO-G360lDcWpPHxuq-rfCdET_cRjQ', '212988080', '', '💕💖美妞💖💕', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_331472caf544418ea811ff12fa07ae22.jpeg?from=2064092626', NULL, '天津', 1780981788805, 1780985354073, 7649156071169557254, 7648947265968639247, '高考选拔不是人才，是天才，对努力的中等生很不友好', 1780957937, '2', '0', '42', '');
INSERT INTO `douyin_aweme_comment` VALUES (11, '98857684055', 'MS4wLjABAAAAPw04NhWDIhdKM_WJ5eRGCwvyeRR1jCUoovWdP-YqLM0', '1540312207', 'L963333832', '💞生而为人向阳而生💞', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oEFABAVpcAO6E7PAE3S2D9wCnemfQouAAcUwID.jpeg?from=2064092626', NULL, '河南', 1780981788815, 1780985354133, 7649181281981072177, 7648947265968639247, '老师都没有变让学生怎么变？高中老师都不咋讲课，而且课本上的基本上不考，全考学生自己琢磨自学，他们要如何替代Al[捂脸]他们实在是太难了[捂脸]', 1780963803, '3', '0', '23', '');
INSERT INTO `douyin_aweme_comment` VALUES (12, '101093065434', 'MS4wLjABAAAA218AfAwC8ZhQSkec4fkYJS9irknwyERJw2vMqZK9En0', '1110100336', 'qf1567866', '芳', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_o8AAmiI4REoPBi4Aef1C0EA0woiYEAAIh1gdE7.jpeg?from=2064092626', NULL, '山东', 1780981788824, 1780985354100, 7649172969906324273, 7648947265968639247, '平时教学不改变，光考试那天题目变了，也没啥意义', 1780961868, '5', '0', '47', '');
