INSERT INTO `douyin_aweme_comment` VALUES (14, '84176763715', 'MS4wLjABAAAA4k2tEhL720Vxa-4JGiPm6MQzBlZ38tUvbfFqqMSrD_E', '291662255', '', '*丹馨*', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_566a37a443e311e3fa22195badbde598.jpeg?from=2064092626', NULL, '广东', 1780981788844, 1780981788841, 7649153582671971099, 7648947265968639247, '说的句句经典[赞]现在的社会也在改革，贾老师说的很好👍不奖励熟练工，而是奖励思考者。不是记住答案，而是发现问题，理解问题，解决问题的能力。 知识本身一定是越来越便宜，而思维能力则会越来越贵。未来只会更卷。真正变得不是难度，而是方向。 所以我们要不断给自己充电🔋', 1780957355, '2', '0', '16', '');
INSERT INTO `douyin_aweme_comment` VALUES (15, '3953456753684819', 'MS4wLjABAAAA4GsLf2Vf1G-Kh13VYX1ehLMFhG_RTf3KRfGh_2qitBwT1GVQsc0WteB1h_E71Z9G', '3674562444', 'dyrqnfwjdg66', '千年白狐', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_okUyBf2eAiODITBUtApgiC5LES9wAAHCDA0An0.jpeg?from=2064092626', NULL, '湖北', 1780981788854, 1780981788850, 7649219311415919400, 7648947265968639247, '思考能力确实特别重要，现在很多学生根本不思考，不会做的题目直接上网搜，一考试就现出原形。', 1780972657, '0', '0', '3', '');
