INSERT INTO `douyin_aweme_comment` VALUES (57, '3949057027867037', 'MS4wLjABAAAACwVRag9s0NGK3VwKvP5q_sS_3qzl68I8nTOWo-L0lnGMoU1HhOFq1RwzLt0sj21x', '91050190830', '91050190830', '拯救世界', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o4l5DfvnAEwDIWC9jAogFCVkEj9AAADtDAdAeD.jpeg?from=2064092626', NULL, '山东', 1780981800734, 1780981800732, 7648643858981421851, 7648601675980725489, '大家不要信评论区那些说数学选择题答案的 不要他说啥就是啥 他说我平时考140，130，120 那他真就可能考吗 也不要说看到自己答案跟人家的有很多不一样的 就觉得自己完蛋了 他答案就不一定是对的 那他胡打上几个答案 或者说故意错改上几个答案 就是故意搞你心态呢 大家不要去对答案 更不要信评论区这种完全没有任何来源和根据的答案 放平心态就好了', 1780838673, '23', '0', '507', '');
