INSERT INTO `douyin_aweme_comment` VALUES (120, '78530872432', 'MS4wLjABAAAAPr8Kiie-VR9Jy_PZ4hVePj1idbk2MtWUN3kGHsHM0Fg', '274492980', '', '小毛哥', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_dbe88db24b8a044a053ef19901aff920.jpeg?from=2064092626', NULL, '菲律宾', 1780981819217, 1780981819214, 7649258585213600549, 7648993794553105674, '不用酸，我北漂过几年当英语老师，真实发现大部分北京的优质高中生父母都是新北京人，全国各地最优秀的那批人在北京定居培养出的孩子。有的人酸来酸去，你们父母辈都不如人家父母，一代不如一代还有脸说话[捂脸]', 1780981800, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (121, '3645613354783531', 'MS4wLjABAAAA9I0SRsscTDIyM7zumIbjpGrn0SnMWMTTA8k0K5BSXXpRI1XvhlHoj53HJIAKbrd4', '2229989174', '', '嘎嘎滴哒霞', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oUUAIeeBAGI2jgAAyjnEeLkbyJ85bQF07RPCFA.jpeg?from=2064092626', NULL, '安徽', 1780981824963, 1780985331773, 7648860032860521275, 7648599264814636403, '我的数学考砸了，我感觉我的人生完了[流泪]', 1780889006, '6808', '0', '67533', '');
