INSERT INTO `douyin_aweme_comment` VALUES (123, '111444625815', 'MS4wLjABAAAAM_anUtA5yz303c4YNH_jRotI3VjSh7P5R93DNvpXGco', '2104711521', '', 'Puppet', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_f0ef7bc853fc97d6762ac7d50c0760d0.jpeg?from=2064092626', NULL, '江苏', 1780981824985, 1780981824982, 7648667095462691636, 7648599264814636403, '平常数学120+\n数学单选ACBDCBBA\n多选AD  BD  ABC\n填空根号3  四分之一   ln2\n有一样的吗', 1780844427, '152', '0', '601', '');
INSERT INTO `douyin_aweme_comment` VALUES (124, '111634094006', 'MS4wLjABAAAAQhne-l1qR0AO6ObHqEqJ-NqL6WCOSM_HCcv1ttlnAQw', '2139476258', '', '柠檬有点甜', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oYkF7ogIiBBAYDMirBCSDzcl4AcAeAAAEbokfu.jpeg?from=2064092626', NULL, '江西', 1780981824995, 1780981824993, 7649258650586366783, 7648599264814636403, '我儿子出直接哭了 妈妈对不起', 1780981816, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (125, '68404538438', 'MS4wLjABAAAAPI_vGe6PSfQUBSV-nf3oBG3DcPnghrIdcILhNTTKCyE', '728473226', '1337376486.', '夜半松风', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_o4qe7A4DmJNqYStFEAAm5AIyDTBNfGeAv2Q7Ef.jpeg?from=2064092626', NULL, '江苏', 1780981825003, 1780985331804, 7648735837806822193, 7648599264814636403, '废了，平时最拿手的数学考砸了，后面没信心了都[流泪][流泪][流泪]真的太难了，最后三题简直噩梦！草稿算了三遍 每次都不一样   真不知道哪里出问题 还是我就是那个问题。', 1780860095, '71', '0', '105', '');
INSERT INTO `douyin_aweme_comment` VALUES (126, '1988333715853358', 'MS4wLjABAAAA6mVn9VfhG2DOLLhhgJ7wKgad4urF6Ejp-bduyNzgqrtJV6HUY_8bFfALn3673yzC', '4036364110', 'qingshuizhenping', 'Shimizu', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oMDEAA3dhfAF74AgIeDzCH3FJmIADDyB7AJNCY.jpeg?from=2064092626', NULL, '云南', 1780981825013, 1780981825011, 7648710126010516273, 7648599264814636403, '其实我一直很好奇，难的话大家不都一样难吗[黑脸]又不是卷子不一样，我高中那会儿做题，如果我感觉卷子很难，只会觉得大家都会觉得难。卷子简单才完蛋，分数会被拉得很高，对于某些只看分数不看排名的人，下次考不到这个分数，会被他们说来说去的，我一直巴不得卷子巨难[黑脸]', 1780854105, '28', '0', '129', '');
INSERT INTO `douyin_aweme_comment` VALUES (127, '773685646207998', 'MS4wLjABAAAAihApGtI-asbsITEp2p7x7xssusZYWiV4soa-so4Fdbc', '3925308073', '993243096.', '早睡早起多喝水', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oAMfsAe78JQA4s7ABdgHIgLIzxAtAUnxGJJ7Ef.jpeg?from=2064092626', NULL, '陕西', 1780981825023, 1780985331791, 7648915515856421669, 7648599264814636403, '有我们17年难受吗？上午考完语文，大家感觉都不错。下午考完数学，我们学校原本招6个复读班，一个班40个人的。但是，数学考完，我们学校的复读班扩充到了16个，每个班60多个人。[捂脸]', 1780901924, '10', '0', '7', '');
INSERT INTO `douyin_aweme_comment` VALUES (128, '4331712440967516', 'MS4wLjABAAAA6B65apfWcp9rqQaQ0iay7Bdl-T7IXWFTBewMfETT0PfLN8mzGU_RFxMW_deDOY1e', '2245713085', '', 'Lawyer.走', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_12ef0f0e35ec20533d2c8244d6f6a6db.jpeg?from=2064092626', NULL, '浙江', 1780981825034, 1780985331846, 7648972501497774897, 7648599264814636403, '我是2010年高考，那时候可能金融危机的余威仍未消除，国家需要一批数理化思维更加优秀的人才，导致数学和理综特别难。现在2026年，确实我们不光需要人才，更需要天才。但是孩子们，你们要相信天生我材必有用，高考失利的大哥目前也可以月入十万。', 1780915191, '0', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (129, '68018637205', 'MS4wLjABAAAAkkZ5-hja7zvn4DpdsT9Qk4sUcduyOu-Qo5Bs8t7ZR9E', '78428871', '', '❤️五月～', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oAF8A2OmeFGABBeAITEDnYfqQAkDgznWJQbEN7.jpeg?from=2064092626', NULL, '云南', 1780981825044, 1780985331834, 7649023129142248251, 7648599264814636403, '其实，如果数学难，对平时数学更好的同学来说，天塌了，对于数学差的，难不难数学考的都差，但是对于数学是自己长处的学生，数学整体偏难，他的长就不明显，其他科目优秀的同学的总分就比他们高出去了。', 1780926979, '0', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (130, '1530969418383207', 'MS4wLjABAAAA5UUdVzBilfAZ6NqD_XkTLgq7jdmBf-PYeRksFZU5-V1gTtP1kh4CssbohpvETUtf', '4198887683', 'yxyqfs1206', '钞票公主', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_662c83bd57733e490449636c95fe24fb.jpeg?from=2064092626', NULL, '湖北', 1780981825054, 1780985331870, 7648918801811096356, 7648599264814636403, '给你们科普一下，并不是题难大家都难这么简单一句话就可以安慰所有人，题难针对的是中等偏上但又不是顶尖的学生，原本平时可以考100多，现在题目难，她们只能考60分，而平时啥也不会的学生也能考50，你们自己看看其中的区别，就拿我们22年考生来说，平时再怎么说考个公办本科没有一点压力，那一年我身边所有的朋友都是民办二本，让我们如何释怀，想复读但是真的没有勇气再读一年，教材也改了，有个朋友复读比22年高考多100分，可想而知，我们22届的学生有多心痛，到现在想起来还是鼻头酸涩，永远记得出成绩那天晚上，在房间锁上门盯着天花板想了一整晚，还是想不通这么努力就考了这个分数，现在四年过去了，我也毕业了', 1780902688, '0', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (131, '3303405171783440', 'MS4wLjABAAAAvpUPewo_9N-CUsXjYmJj5dZZiT_DZMj0L-d5_c5VXPPwd19Lsf93w_AqZaOG1K3i', '35350022545', '35350022545', '離🍃', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_e0aa1ea05bbdc9da29f77e4c131b429e.jpeg?from=2064092626', NULL, '浙江', 1780981825064, 1780985331862, 7649063183979004687, 7648599264814636403, '数学和物理，不会就是真不会啊，这两个学科难度提上来，才是真正鉴别学生优劣的手段，优胜劣汰，难，大家都一样难，又不是一个人难别人就容易，挑的就是在这样的难度下能杀出来的“优等生”', 1780936309, '0', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (132, '607403069156755', 'MS4wLjABAAAA3YbAFEs1YFEHslfWzpDx8Ozsur_E5P81GcBxONWfC1I', '44689594551', 'yy07_1022', 'Toska', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o0ACAvPLBAA1iAoAfliWqREHECNIPXQg84ebwA.jpeg?from=2064092626', NULL, '河南', 1780981825073, 1780985331896, 7648959042639790899, 7648599264814636403, '感觉自己真的很傻，英语平常都能考110,120，这次感觉考的特别烂，也不知道为啥在那反反复复犹豫，都没时间了，前四科感觉都不好，家长还给准备的花，拿着我都好愧疚。[流泪]', 1780912058, '24', '0', '34', '');
INSERT INTO `douyin_aweme_comment` VALUES (133, '100185044073', 'MS4wLjABAAAAPzCNm6sPhz_UZRcLOSei9o7eiujaXSihW5YhW9Du-xo', '3609704301', 'dyznjkxgs333', 'koi6', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_7fe6fe030d304a4f7660e8c6c4b934ae.jpeg?from=2064092626', NULL, '江苏', 1780981825082, 1780985331917, 7648883420219114289, 7648599264814636403, '高考在哪报名你们也不告诉我 这下好了吧都考完了 我错过了[流泪]', 1780894451, '13', '0', '87', '');
INSERT INTO `douyin_aweme_comment` VALUES (134, '1286881289180366', 'MS4wLjABAAAAPdrUSB6sgusmLIiHhbM3LS_ACnCveKLxWyoP6dR0HTYnqrSifrOJyhM6EmvMmgRL', '51906480777', '51906480777', '🌈🌈㏂', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ooDEAAxkEFADhxAwI9DDnYoMQPAAIepFKEGfCh.jpeg?from=2064092626', NULL, '吉林', 1780981825091, 1780985331926, 7648964176555426619, 7648599264814636403, '同学们听我一句，我23年的，数学算不上顶尖但也不算差，最高考过145，平均125，但是高考不知道为什么真的是鬼附身了一样考了七十多，现在还是上了211，虽然和预期差很多，但是我想告诉你们，你认为的考砸其实真的不算什么，放平心态，我就是知道自己考砸了但是还是努力完成了后面几门，别放弃', 1780913253, '4', '0', '57', '');
INSERT INTO `douyin_aweme_comment` VALUES (135, '475404096777788', 'MS4wLjABAAAAqjXCbKDlpf5-4m5rQgnEq4IvoCjnFYxHdhcBnRn-394', '4027056391', '2006.03.15z', '1737', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_osln4rDfIFAiQeFQ8AEQAiBAJs4Kf7zDT0LFgT.jpeg?from=2064092626', NULL, '湖南', 1780981825102, 1780985331907, 7648688684972016443, 7648599264814636403, '我真的要吐血了 填空第三个到底选啥啊今年数学真的要杀了我一样看都看不懂都超纲了 神了填空第三个你们是选的m7还是m14 我本来想选aw的但是直觉告诉我是asval真吐了希望蒙对了[流泪]', 1780849111, '32', '0', '88', '');
INSERT INTO `douyin_aweme_comment` VALUES (136, '7402536964614538297', 'MS4wLjABAAAAMrjc67X85hhBA6oyWBK-db9c3KLSZQNm_j7N6mrKCil_RVj-51BR7Wq3JZMDNRVk', '67542770137', '67542770137', '卡拉米', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_fa0e060a36c62ba3000806cef234c92d.jpeg?from=2064092626', NULL, '山东', 1780981825111, 1780985331963, 7649157984820839217, 7648599264814636403, '其实真的通过高考，改变人生的学子屈指可数！顶尖的学府只要顶尖的人，而顶尖的人又有几个呢！有句话叫，有些东西出生时有就有了，没有这辈子可能也就没有了！！每年有那么多普通大学毕节的普通学生，又有几个是真的成为人上人的！！不是我抱怨，而是在中国这就是真的事实！', 1780958379, '5', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (137, '50817239177', 'MS4wLjABAAAAh1itukVU9v819aJqxqwzqiaAbBcAETc7PSU8rtXWs0Q', '1992057210', '', '天洪精品车行', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_23f500005c648439dd93b.jpeg?from=2064092626', NULL, '江苏', 1780981825123, 1780981825120, 7648926418117772058, 7648599264814636403, '各位优秀的学子你们好，成绩单只是一张纸，证明不了什么，掩盖不了你以后身上的光芒。学校永远不会教孩子在外如何保护自己，如何防诈骗，如何应对突然事件（水电火地震），如何独立生存，如何挣钱，如何投资，如何理财，如何规避风险，天不生无名之人，地不长无名之草。每个人存在都有存在的意义和价值所在。三百六十行，行行出状元。尤其考的好不如活的精彩，其实社会才是一所真正的名牌大学。加油！[灵机一动][灵机一动]', 1780904462, '4', '0', '12', '');
INSERT INTO `douyin_aweme_comment` VALUES (138, '2840738667436759', 'MS4wLjABAAAAEtUwSYRYOTwdOr_kyeUisPjpZAzyEvhsXF_hI9pbCyedVdTk3EPug29IIDtz3UcL', '3495592617', 'dyaa44y1ta19', '笨笨的乡巴佬', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_owDEDIgqgAEgAJFqeft4syzC9A7dNhAxmA53Ad.jpeg?from=2064092626', NULL, '广东', 1780981825134, 1780981825131, 7649258000734208814, 7648599264814636403, '摧毁年轻一代、彻底毁掉一个家庭希望有无数阴损招！', 1780981666, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (139, '95952726469', 'MS4wLjABAAAAKjc45j5dRra5PWb2j7nn2Ex1picMLn9keQZOzemWPoU', '619874739', '', '林重树.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oEkffdAoQgoef4AMllXP8Yfp8gzfxdA4AAgtHa.jpeg?from=2064092626', NULL, '四川', 1780981825144, 1780985331974, 7648715220459160357, 7648599264814636403, '试卷出的太简单太难都会拉不开差距，甚至太难了，有些题差生中等生都不会做，直接中等生跟差生都拉不开差距，这里的差生指的是数学稍微有所欠缺的，名次只会不升反降，这种严重点是属于出题事故的', 1780855294, '21', '0', '83', '');
INSERT INTO `douyin_aweme_comment` VALUES (140, '3478469432588077', 'MS4wLjABAAAA5e7mu5NhdFS1wFRy5NOiAK6DlJYUKH62CVkUuF3etOkVMXnkDNDXgTcfaQ7RqJcg', '2802228810', 'm1562510284', '挽歌', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_eefb7a0ee3bb3ae7e0e283c937831b60.jpeg?from=2064092626', NULL, '安徽', 1780981828909, 1780981828904, 7648641091542270730, 7648599264814636403, '我们高考那年，考前一个月数学老师突然人间蒸发了，因此全校师生疯狂研究我们数学老师的解题思路，高考结束后才知道，数学老师是因为嫖娼被抓了', 1780838029, '1293', '0', '48045', '');
