INSERT INTO `douyin_aweme_comment` VALUES (149, '527384565783150', 'MS4wLjABAAAA-QE7akAuXDaVQMkoN-zQkZNwd02YCqR9JsKsJfJgSnU', '3864419987', 'zoucc00', '五千年前的古董', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ogjPKAYsXeAVuEQoCRFfEEwMbeFAjgIL9ADnA1.jpeg?from=2064092626', NULL, '四川', 1780981835158, 1780981835156, 7648975912080704293, 7648860424963640619, '本人不才，参加过两届高考。第一年物理超简单，没拉开分数。第二年据说物理超难，我物理超了我们补习重点班大部分同学30分以上，让我干到了重本线30分以上。\n高中毕业20年，考个试，裸考，有很多力学知识（大学没学过力学），我用高中物理知识连估带猜，都还能干对了一半。[呲牙][呲牙]', 1780915986, '1', '0', '5', '');
