INSERT INTO `douyin_aweme_comment` VALUES (161, '104995663398', 'MS4wLjABAAAATrJBsj_4iJbrbnBjFVYKyWlL0UKmU50zb_Uq-tNFMxs', '3328950587', 'Aio_mySelfish', '捡瓶子拉扯小三孩子被老婆打出屎', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_0639c05e48a5112fbe552e850b66c933.jpeg?from=2064092626', NULL, '广东', 1780981841154, 1780985348090, 7648562778650821433, 7648498783520689454, '犹豫 很多人做事都会犹豫 唯独一件不会犹豫的就是我记得一天晚上我发烧了外面下着暴雨 我的妈妈一点也没犹豫背着我就跑去医院', 1780819795, '7716', '0', '268291', '');
INSERT INTO `douyin_aweme_comment` VALUES (162, '62172698943', 'MS4wLjABAAAAdUVPHmz0CDkxUXKTbNWE5UxWbPI_Vl3mVqYg8RiJO0g', '26532099', '', '芋泥脑袋𓈒◌ 𓂂', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_10637241e9c85cf97ba86cf0dda05211.jpeg?from=2064092626', NULL, '河北', 1780981841176, 1780985348110, 7648546233874989866, 7648498783520689454, '犹豫，只有妈妈会毫不犹豫，记得那个下雨天，我发烧了我的妈妈毫不犹豫的背起我……', 1780815943, '2588', '0', '89692', '');
INSERT INTO `douyin_aweme_comment` VALUES (163, '3490308835258988', 'MS4wLjABAAAAOPSpWNP8ZA77gj8gHLcRvHpeHTz0ZAPhRyNQBkvokXEoSDu4gbJ3B46fTW0RlFmD', '35136167914', '35136167914', '晨风', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oYqAeFjowECEeAi97E2I3mEAAIASwxfADUyBi6.jpeg?from=2064092626', NULL, '山东', 1780981841187, 1780985348123, 7648589817424462629, 7648498783520689454, '犹豫这个词太妙了！太好写了[微笑]能写出深度，但是尺度把握得还很好，甚至比那个原韩国作家更贴这个题[捂脸]最主要的是考场思维限制，很难想到合适的词，太容易狭隘了', 1780826091, '8', '0', '542', '');
INSERT INTO `douyin_aweme_comment` VALUES (164, '4278931530975816', 'MS4wLjABAAAASmzjGJs7iznMOHyLCtH2WWXRlTJo2ydWF0ADDgdBz4nw0CJQg8L8WtfE0myzSfne', '2227365180', '', '优享生活', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oMCL9AnR4HqbIAfOFgGkNYDDAsPeIAlEAQgAAP.jpeg?from=2064092626', NULL, '重庆', 1780981841197, 1780985348140, 7648575375404303147, 7648498783520689454, '过去：犹豫 = 拖延、不敢尝试\n现在：犹豫是蓄力、观察、准备，是为了更好的行动；没有深思的行动是蛮干\n成长：从 “急于求成” → “厚积薄发”\n时代：创新不是盲目试错，是审慎探索、稳中求进', 1780823069, '97', '0', '4422', '');
INSERT INTO `douyin_aweme_comment` VALUES (165, '3195623600293481', 'MS4wLjABAAAAsCN5KeBZgait0swP7VlUGiakjPbWQgu01NOAvk-rc2O6uEkwCJ-mFQaah0w9QsBz', '37383330091', '37383330091', '没有灵魂的机器人🤖🤖🤖', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ooeGNAGK4AyJBLeADGfzB7mEa6xbIa0ABTbAEn.jpeg?from=2064092626', NULL, '广东', 1780981841208, 1780981915722, 7648524468487275321, 7648498783520689454, '我好像看到过，人类的犹豫，换个词叫踌躇，在人与人之间交流时，面对痛苦，不甘，悲伤等的宣泄时，人类所流露出来的迟疑、犹豫、欲言又止，变成了对宣泄人的体谅，安慰，感同身受，不同于AI的信息收集的加载，而是人类在面对痛苦时该有的情绪流露…', 1780810876, '12', '0', '506', '');
INSERT INTO `douyin_aweme_comment` VALUES (166, '50942273656', 'MS4wLjABAAAA8CksN9DZB7h3SvpI_ZEkwdctzA9L3N8g1chBH8Ru4Xw', '43610143', '', '半生缘', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_317050001f5988e45f124.jpeg?from=2064092626', NULL, '湖北', 1780981841217, 1780981841215, 7648635181163053883, 7648498783520689454, '“有一个人类有，但AI是没有的，是犹豫，当你倾听某个人的烦恼和痛苦时，你可能会咽下一些话，会犹豫，会考虑要不要说是存在这样的差异的。在这些踌躇中包含着体谅和关心，比起流利快速的AI答案，人类粗糙的沉默可能会更加安慰。”——韩国女作家 金爱烂', 1780836653, '2', '0', '65', '');
INSERT INTO `douyin_aweme_comment` VALUES (167, '66621959508', 'MS4wLjABAAAA_uVDN5Jt8kuYsZmkMnJCLEsKSegb_d8KifIV5CeMjOQ', '155875078', '', '🌈风生水起', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_45b9acae338024888308ab5982612d7b.jpeg?from=2064092626', NULL, '山东', 1780981841226, 1780981915729, 7648599509366915899, 7648498783520689454, '1949年以前，前辈们是“犹豫”的，如何能打破局面，又如何看到未来，每个前辈都是在摸索中前进，为的是什么，为的是赌那一缕曙光。\n而今天你们也是“犹豫”的，是为了如何传承前辈们的精神，如何理解“为中华崛起而读书”，并为之终身奋斗。', 1780828348, '2', '0', '29', '');
INSERT INTO `douyin_aweme_comment` VALUES (168, '58526199675', 'MS4wLjABAAAAL6qiwe0BM5YlHmjvZTnK6TRs29VCoMZJMttDHsL8R5g', '80555285', 'c20001014', '$uai', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o8EAjyEAMCcAPgeKLbIADfhAUiz2jcAV4tAymD.jpeg?from=2064092626', NULL, '江苏', 1780981841236, 1780985348223, 7648609842685117221, 7648498783520689454, '犹豫这个词真的不错，犹豫虽然是一个贬义词，目前人类和ai最大的差距就是犹豫，那么在不久的将来，假如给ai加上犹豫的情感，那么ai机器人会像三年前我妈妈冒着大雨毫不犹豫的背起我送医院吗……', 1780830754, '2', '0', '62', '');
INSERT INTO `douyin_aweme_comment` VALUES (169, '4024668228690910', 'MS4wLjABAAAAVaYnHuLnYwWbJtzgjD1TgS8D7BD61mZbYoXQKYcLK0myv_jmKnl8A-aIW_pz9WGq', '56321786857', 'LLJ5l5l5j', '倔脾气', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oUf1sieAAiBAVF5ik5iNUEAqEmARIwC4vAAnLA.jpeg?from=2064092626', NULL, '湖南', 1780981841245, 1780981915747, 7648579331733013305, 7648498783520689454, '就是“长大”呀\n小时候以为做长大了就可以想干什么干什么 不用被家里束缚 可以自己最主\n可是到现在我真的长大了我才明白不是长大了就拥有了所有 也不是长大了就自由了', 1780823650, '7', '0', '72', '');
INSERT INTO `douyin_aweme_comment` VALUES (170, '3153879180257182', 'MS4wLjABAAAA7chep4d7yz5AWKwFIaviTwyyMfq-8z4ym-1wvDtqqzQGiqPgNTTdCwMTIJ7XqlHa', '64045299565', '64045299565', '英文哥', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ooAhPp6NeyhKCNApCazrnDfcAd11gAME6KgAIA.jpeg?from=2064092626', NULL, '上海', 1780981841253, 1780981915757, 7649258319198307091, 7648498783520689454, 'AI1秒钟做出了选择\n人类犹豫了一个月，做出了同样的选择', 1780981739, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (171, '1275025199739144', 'MS4wLjABAAAAjdugiPPkqb_iMvtA0OamfWBj8QQZ9hBlZN1iMYWG9JW37g8SoQeBthKOAJVFDLTm', '3579744081', 'Zzz0312l', '朱庖子', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_aad45d228ebfdf5f53fb90ac81dfb7fe.jpeg?from=2064092626', NULL, '浙江', 1780981841264, 1780981915779, 7649258225293067014, 7648498783520689454, '“快餐” 还有“喝茶” 小时候觉得就是吃的喝的 长大了才知道还有别的意思 [灵机一动]', 1780981717, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (172, '85987367544', 'MS4wLjABAAAAopme_W11zgmE1fXqLl0-OfMVUB7Ne5KwFoSGX6oYbL0', '200585388', '', '非人哉', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_a3138a8283fa2b19ad925a48f67573e0.jpeg?from=2064092626', NULL, '云南', 1780981841273, 1780981915764, 7648540377251250980, 7648498783520689454, '听他的描述我第一时间没看懂，去搜了一下。和ai博弈毫无关系，和最大的差距也没关系，和需要的品质也没关系。只是因为ai的回答快速却冷冰冰，犹豫反而体现了人类无法表达的共情和真挚，这些自有的缺陷反而是人类情感无法替代的表现。就她这个理解和表达能力能写好就怪了[捂脸][捂脸][捂脸]', 1780814580, '14', '0', '23', '');
INSERT INTO `douyin_aweme_comment` VALUES (173, '1225299750293971', 'MS4wLjABAAAA4LIFol2nlK4_FEWX6qgEg06mqpmuayh1ApGzgOVWHfo2yfT-3QW4E_EraKzCTIOR', '60998907242', '60998907242', '爆炒灭火器', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ocey7RAqGIbIB4S2JAgAMaHepEngfLQGAt8EgX.jpeg?from=2064092626', NULL, '浙江', 1780981841281, 1780981915773, 7648545414370919217, 7648498783520689454, '我看到这个题目之后，第一反应是英雄，因为英雄这个词好像在我们的印象当中是很大的，但是在现代社会有很多不起眼的小人物，也能称得上是英雄，如果用这个主题的话，那可举的例子可太多太多了', 1780815752, '4', '0', '11', '');
INSERT INTO `douyin_aweme_comment` VALUES (174, '52788787290', 'MS4wLjABAAAAuNWxAxhbtUl_c3pdwx9Kc43IuPot25GZigo1aiYJ1B4', '2933272174', '253289781d', '☞心☜', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_c3aa85dd745147f98516b6cdd7973cf7.jpeg?from=2064092626', NULL, '上海', 1780981841292, 1780981915789, 7648597093284676410, 7648498783520689454, '曾几何时，“躺平”一词被视作消极避世的代名词，意味着放弃努力、随波逐流。然而，在当代青年的语境中，“躺平”有了新的解读：它是对过度内卷、盲目竞争的一种反思，是人们在高压生活下寻求内心平衡、回归本真的选择。它不是放弃奋斗，而是以更清醒的头脑审视生活，拒绝被无意义的忙碌裹挟，追求一种更有质量、更可持续的生活方式。不是我写的[捂脸]', 1780827785, '2', '0', '19', '');
INSERT INTO `douyin_aweme_comment` VALUES (175, '52966350193', 'MS4wLjABAAAAbkuN7Ry0HxVEVmGbZQbpt5TQLwBICvtso_fzDGqHeMM', '1280393022', '', '那咋了。', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ea225ac7688749a1bf1eb2e7064e51a1.jpeg?from=2064092626', NULL, '日本', 1780981841301, 1780985348263, 7648538055675413294, 7648498783520689454, '爱国   直接写对爱国的理解变化，小时候以为爱国只是好好读书，心中有祖国，中学时以为爱国只是一致对外，牢记历史使命，后来才明白爱国可以是在全球各地，哪怕是再微小的行为，只要是为了国家利益，为了民族复兴，我辈义不容辞。', 1780814039, '5', '0', '44', '');
INSERT INTO `douyin_aweme_comment` VALUES (176, '1003220362868077', 'MS4wLjABAAAAabUhxC9Wd2XFAlu4ElHw-Z796ME32YQ6ALSwAzKuiuKblA9YqqTyrkeid84Drw4t', '23733598992', '23733598992', '种地大户', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_4b0d34822a311b730c58ffc8594b630a.jpeg?from=2064092626', NULL, '山东', 1780981841312, 1780985348156, 7648523585803780901, 7648498783520689454, '我想到的是新生，小时候觉得新生是诞生是新的东西出现，慢慢长大发现新生是青年力量，是我们这一代身上肩负的重担，联想到国家也是面临新的挑战，要不断创新，破茧重生。', 1780810670, '30', '0', '519', '');
INSERT INTO `douyin_aweme_comment` VALUES (177, '97880607243', 'MS4wLjABAAAA8aXZMkjGvhKGSXcLxOXTFa_q1WoX_6CJRm8u1MNiHwA', '889060129', 'Lb6868', '小僧来阅经了', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_f6a5000ee3b678acf181.jpeg?from=2064092626', NULL, '浙江', 1780981841321, 1780981915815, 7648507120656532282, 7648498783520689454, '这个基本上没高分，她把AI当材料了，太微观。实际的材料是时代之变，社会之变，历史之变，青年是常新，对这“三变”引发怎么的认识改变', 1780806837, '7', '0', '57', '');
INSERT INTO `douyin_aweme_comment` VALUES (178, '1394595058420151', 'MS4wLjABAAAASaeabjWWg1Fv3sm3TdTtMmlKQj5bd3CS0Gxvprn6ohzcgznPU4nFjddJ82EvpKRq', '61033270894', '61033270894', '学着石头忘记时间', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o0ISvgACIEusJJABwCTBfD9EfQnDEGAfAAHFH7.jpeg?from=2064092626', NULL, '陕西', 1780981841331, 1780985348247, 7648556169460007721, 7648498783520689454, '我写的话应该是“舍得”，\n第一段：小时候舍得是单纯的舍，\n长大后明白了是先舍才能得\n第二段：于人来说，不可能事事如意，想要得到一部分，就必然会失去一部分。想要考一百分，那么就要舍掉休息时间……\n三：于国来说，复兴历程并非一路坦途，多少志士为之舍去所有……\n四：于社会来说，“舍得”是一种必备的技能，没有人能够尽善尽美，有时候无用之用也是一条道路。如今社会上抑郁者、不得志者凡几，全是因为他们不懂“舍得”。栎树无用，却枝繁叶茂，仰赖千年；橘李结甘可之果，轻者折其枝，甚者绝其干。栎树舍其用所以得长生，橘李欲尽美，所以绝其嗣……\n结尾：所以……', 1780818257, '5', '0', '37', '');
INSERT INTO `douyin_aweme_comment` VALUES (179, '7403714409761276988', 'MS4wLjABAAAAtjQbwCfcWQ02aFAP9z3IlNGvS8K1hxJ1yNXVeAXqK58etcCIR8WQ2AnfvNnsaKBG', '26158563484', '26158563484', '蹲在橘子树下', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ogIAfFmm3CAWA1DPQf8oACAgEtcWEv8jzFAA9C.jpeg?from=2064092626', NULL, '江西', 1780981841343, 1780981915836, 7648525801474704180, 7648498783520689454, '我想到的是“骚”，现在这个词充满贬义色彩，但曾经文人骚客，这个词可是很好的。从时代入手就是，词语的转变总伴随着时代的变化，曾经美好的词汇加以命名，是时代变迁的无端污蔑。但是越来越多的人为他洗清这些原本不属于它的含义，展现出这个字原来的面貌。这真是时代的进步，时代的改变，越来越多的人不再追求于表面以及人人传颂而带来的偏见，而愿意深挖本质。正如社会中有许多的事件本是善意而来，却被人以各种谣言的形式加以污名，但是真相总有一天会展现。总之，我大概会以这样的形式进行写作。我觉得可以加入网络暴力，行为曲解的一些元素。证明人们思想的进步，引入时代的起承转合。[泪奔]我第1次看到这个作文题目，我临时想的。也不知道会不会跑偏。', 1780811187, '62', '0', '426', '');
INSERT INTO `douyin_aweme_comment` VALUES (180, '103831624860', 'MS4wLjABAAAAU2ZoRnuArXTQuUbYriF9AmAnk_2jIfsrHN4_cneH0Os', '1379944591', 'wzj.0310', 'Zev J. Wu', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oAKAIJALGIAzC7AglNBqVGQrjesTGetE8ZeSXq.jpeg?from=2064092626', NULL, '江西', 1780981841352, 1780985348208, 7648859827494241083, 7648498783520689454, '我记得一个很明显的例子，就是我们的验证码还滑块 他是怎么判定你是不是真人的呢？因为机器的话它可以秒到正确的位置，而且速度绝对快，而人类需要手动的拖动可能会有误差会有犹豫的时间或是犹豫的一个步骤，犹豫的一个情况，滑块验证真人跟机器就是通过这个来验证', 1780888958, '1', '0', '27', '');
INSERT INTO `douyin_aweme_comment` VALUES (181, '1502366381902464', 'MS4wLjABAAAApksOkI0F7EMtId8CEunyMrlPTWGpOTDuqdlZ8VmCqcQXq7p_tDdUtFB_rLV-rqez', '48751955702', '48751955702', '抖音精选官方账号', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_c0e5aad3548629d5e69f3104afa86d12.jpeg?from=2064092626', NULL, '天津', 1780981847256, 1780985307064, 7648509508155949876, 7648330461677491674, '如果高考作文以“你”为题，会写成如何？ 长按下图识别二维码，或上抖音精选搜索#抖音精选人生作文生成器 ，生成专属于你的“人生作文”吧！', 1780807854, '263', '0', '28962', 'https://p11-sign.douyinpic.com/tos-cn-i-p14lwwcsbr/e17d1df9934a412c821199e7d14cefd4~tplv-p14lwwcsbr-7.image?lk3s=7b078dd2&x-expires=1781006400&x-signature=1dxPkrCFm46uYJPsPILs6Fe6U24%3D&from=2064092626&se=false&sc=image&biz_tag=aweme_comment&l=2026060914082618218C0E62F9611077E0');
