INSERT INTO `douyin_aweme_comment` VALUES (264, '63272934591', 'MS4wLjABAAAATSGzQnBXUHSAZddhBPo60EuQT32ZpcS4cWP2uKICPs8', '89079677', 'lizhichengbaby', 'mist', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_9bd852c9677d9fbf1e281c3f7a43ee50.jpeg?from=2064092626', NULL, '辽宁', 1780981887036, 1780981887031, 7649181851941094179, 7648939065064115465, '答案很简单啊', 1780963936, '2', '0', '8', 'https://p5-ex-gddgtc-sign.douyinpic.com/tos-cn-i-p14lwwcsbr/441655bfcd0644eeb871c089b3bddf18~tplv-p14lwwcsbr-7.image?lk3s=7b078dd2&x-expires=1781002800&x-signature=FPVdHisLQjqf%2B%2BIq1rBCDxQ16AY%3D&from=2064092626&se=false&sc=image&biz_tag=aweme_comment&l=20260609131126F8338CB0FE19FB0F9E2D');
INSERT INTO `douyin_aweme_comment` VALUES (265, '7621757204837008441', 'MS4wLjABAAAAbRB4obRCEtnj7VV1PuBcfV7o65_DAEHCoXi8RUuoeaXQ2Zjuj-BcLforGfEcdLgA', '63072247150', '63072247150', '鹏', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_okE0QeC0Wf7XcinDxHDBGwAAnXEPAZCARIAoit.jpeg?from=2064092626', NULL, '江苏', 1780981887049, 1780981887046, 7649075899815985957, 7648939065064115465, '这题如果它是套路题，练多了，其实不算难。绝大多数普通学生没见过这种定义题，我只能说从出题思路和目的来说，是失败的。设置高考绝不是筛选顶尖人才的，而是为了给广大莘莘学子一个公平竞争的渠道。选拔顶尖人才可以通过竞赛、保送等等方式，不必要通过高考。一定要把（天赋普通、很努力）和（天赋普通、也不努力）的学生区分开来。我当年江苏高考数学141+36分，也在南大读了应用数学硕士，这题我也花了26分钟才做完，而且还不是拿了全分。这种题放到高考里，真的对学生不负责任。', 1780939268, '1', '0', '12', '');
INSERT INTO `douyin_aweme_comment` VALUES (266, '98483111585', 'MS4wLjABAAAAMYMWw3EefEkgXjPtvgHEh46Ii58sEj1olC_lR-Fk52k', '3541457342', 'yuankuai666', '小金鱼', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_8f8abdc7f8bf41b9b06eb254914677a9.jpeg?from=2064092626', NULL, '湖北', 1780981887060, 1780981887057, 7649161590914663217, 7648939065064115465, '现在的教学有问题，教学用的是老思路，出题的是新大陆，[捂脸]', 1780959218, '5', '0', '32', '');
INSERT INTO `douyin_aweme_comment` VALUES (267, '1222286493879207', 'MS4wLjABAAAAl3_QntPgBI0AjCGWYnlzoJDrza3bJirH7IgvqK-jVMVmpv13HMMh448s4Zs4jOUZ', '48311710284', '48311710284', '时꙰间꙰', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ok59hgZAPELZiBdAAAVFAIbRgIvAaAEP5aiBE.jpeg?from=2064092626', NULL, '广东', 1780981887073, 1780981887071, 7649258833722770185, 7648939065064115465, '当年高考一百三。我看了一眼有思路，但很多定义都忘了。[捂脸][捂脸][捂脸]得亏毕业二十多年了。', 1780981859, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (268, '2414146894435243', 'MS4wLjABAAAABWskYKJ81FOOrM8P-UOsifuV8iLUgmJF0iM3BcUGaf2QefY5hV0s7O05bklzDGxt', '2158741714', '', '红烧大仙贝', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ogEsIAEA9pN7AjDpzFDOfGSYFUfAIEAwnEKQCu.jpeg?from=2064092626', NULL, '安徽', 1780981887083, 1780985442192, 7649094292351206163, 7648939065064115465, '我感觉很恐怖，这不仅仅试一次考试，是整个AI时代的一点火苗，或许从此人类就要一分为二了，有数学能力的人，和其他人……数学人将会是高精尖科技的基石，而其他人能做的工作或许会一点点被AI吞噬。也许能夹缝里找到一点生存之道，但是宏观面上，不知道未来在哪里', 1780945100, '9', '0', '18', '');
INSERT INTO `douyin_aweme_comment` VALUES (269, '976799098486664', 'MS4wLjABAAAAAzVxzKMgAcLAvmcI8FXpNDIczfpN7ObLOYacmEGpJHg', '54855742974', '54855742974', '🌊 Blue whale 🐋', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oMW9puEFRAkVN0CuAxdxLegIDfA5FAAIwCAmhQ.jpeg?from=2064092626', NULL, '山东', 1780981887093, 1780981887091, 7649258724063200037, 7648939065064115465, '就是选有数学天赋得或者说摸到了数学规矩得门槛能够融会贯通。就好比练武术，以前是套路比试，比如咏春，就比咏春，一个个上看看谁动作完整，优美。现在是自由搏击，套路不限制，各家拳法随意发挥，谁底子厚，融会贯通的好谁赢', 1780981833, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (270, '104887077525', 'MS4wLjABAAAAxA2zEjLbbDiaUIuURq7bktlZnsNz-NEvNxDJVqX8Das', '1552873468', '', '杨小蓝', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o0CgIoNeAARz9CzzAAgfB2zDENdNyahCXAuE2A.jpeg?from=2064092626', NULL, '四川', 1780981887103, 1780981887101, 7649234161023435571, 7648939065064115465, '08年高考数学140分，现在找不到工作，待业[泪奔]', 1780976114, '16', '0', '14', '');
INSERT INTO `douyin_aweme_comment` VALUES (271, '111065749860', 'MS4wLjABAAAAviYQNoMbaAflb3NbI6ZNnBJ3wiwU3mrSxOXnswbJ048', '3878329009', 'zou49028', '人微言轻', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '辽宁', 1780981887108, 1780985442244, 7649035661651428111, 7648939065064115465, '我自认为不是个笨人，几十年过去了，我到现在还纠结初中二年级的代数解题，老师的一句借尸还魂直接把我搞懵了，我连原理都没搞明白直接让我解题，后来上了大学，高数老师还是让我们用微积分解题，至于原理我到现在都没搞明白，没有人讲原理，只讲怎么解题。', 1780930199, '5', '0', '10', '');
INSERT INTO `douyin_aweme_comment` VALUES (272, '68485851230', 'MS4wLjABAAAAqaxM1fVZJ8ouyEeR9tiD7vBIUjidMvqKJuIjvSXeXuY', '339476695', '', '没烦恼.🦢ིྀ', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_8db72d19e62406347c064fb61ba972f6.jpeg?from=2064092626', NULL, '辽宁', 1780981887118, 1780981887115, 7649195109774754597, 7648939065064115465, '也许在多年的实践中，以往的高分在国家尖端领域中并没有表现出突出的作用，相反只是平庸的服从命令，搞搞基础问题。因此推导出刷题的方式得到的高分是满足不了国家对尖端人才的需求的。所以到底选拔什么样的人才，怎么选拔人才，成了现在需要思考的问题…我想每年的试卷出台，也并不是一个出题老师能够决定的，而是经过一个团队深思熟虑的决定。相信有思维的孩子一定金榜题名～未来为祖国做贡献～', 1780967022, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (273, '92029362415', 'MS4wLjABAAAAkgMDO1PmkYAKMrKCa_o5uKPwkkrXynN2_kGCJMOo7jw', '948032961', '', '小月亮', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o8eBaAJnAMAIwAhymFNfhcTsECxtlANgXgzrAA.jpeg?from=2064092626', NULL, '新疆', 1780981887124, 1780981887123, 7649148762087228218, 7648939065064115465, '说白了就是国家现在往发达迈进，需要搞科技，推动科研进步，那科研进步需要的是数学思维与推理，高烧脑型人才，而不是刷题机器。普通的80%都会做，但是招那么多。。哪来那么多办公室让做，所以国家现在需要捡漏，捡漏什么？抗压能力强，能脱颖而出的人，现在是数字化竞争时代各位别忘了', 1780956233, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (274, '105715674703', 'MS4wLjABAAAA92MUQ4RfTIghIRg9CkX2W2WU8AIjeW5ppPkrN4XtgUg', '2317837059', 'sunyi90281', '℡巅峰鬼鬼sy', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oIkDfADom4CE5F9epjOUOAnAwEaiCTQIAA2uEm.jpeg?from=2064092626', NULL, '吉林', 1780981887136, 1780981887134, 7649258846784062245, 7648939065064115465, '别搞我啊，我是新高三啊[流泪]', 1780981862, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (275, '101065600936', 'MS4wLjABAAAAfoOh7HwSSKtFEJSydyeWyYDN4HQSbycuN4OqRnur_kI', '1107704923', '', '🐑～', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_927f395005b74a45a0ef4faa9f7a47af.jpeg?from=2064092626', NULL, '湖北', 1780981887151, 1780985442141, 7649217443898770230, 7648939065064115465, '这题最后一问真的很像数学分析从定义出发运用数学语言逻辑推理，非常考研数学素养，我觉着挺好。数学本该如此，注重分析能力，而非解题套路 。数学教学也得回归本质，注重能力的培养而非解题套路的记忆 。', 1780972222, '1', '0', '5', '');
INSERT INTO `douyin_aweme_comment` VALUES (276, '3642015306750568', 'MS4wLjABAAAAXqdCMrQJkxuvYh1Al3ZqjwnoxVlvpTiewlUUqXfq1bcM7hPQ1JZfN9tx7ch8rRPa', '54937464617', '54937464617', '伪', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '江苏', 1780981887159, 1780985442175, 7649150638815281961, 7648939065064115465, '\"大转弯\"也不能无预警、无过渡、无适配，突如其来地玩\"赛道硬切入\"呀！考的内容与方式，与所有高中现有的数学教学、训练、备考的内容与方式完全脱节，导致考生和教师们对这份卷子是日常零训练、体系零覆盖、备考零铺垫。命题人眼里只有1%的精英学生，而中等生甚至绝大多数的优等生，在他们眼里，全是\"刍狗\"。', 1780956669, '2', '0', '7', '');
INSERT INTO `douyin_aweme_comment` VALUES (277, '2374596326335726', 'MS4wLjABAAAAenEbf6HPk3fuyXAqRPESBXDsFa7eraJyCPEv6wMYdmogaX470r8s1GPbKEn3LSv2', '60602181462', '8090smile', '美好的生活®', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_40d833ca9c33794fa7e05725b521ea6a.jpeg?from=2064092626', NULL, '河北', 1780981887168, 1780981887166, 7649230871211868977, 7648939065064115465, '最核心的是需要人的脑子能战胜AI，从中获取思维，改善未来AJ，与其说挑选独特思维，不如说利用独特思维进化未来智能，现在的选拔已经不只是只是选拔，更多的是将选拔出来的应用到未来智能', 1780975348, '1', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (278, '86782727455', 'MS4wLjABAAAAU6p22MXZnCdRDRr7dINvXRQ9SRMswchUIVXCBMLqhew', '3941659787', 'dymwzoh3crmx', '野狐禅', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_9f9db0e9899791e502879ca348d9f769.jpeg?from=2064092626', NULL, '浙江', 1780981887176, 1780985442217, 7649052633039602481, 7648939065064115465, '关于这一点我非常认同；其实，任何一个数学学的好的学生，最基础也最有效的办法，就是把所有学到的公理、定理自己重新证明一遍；这个重新证明的过程，就是理解该区块解决什么问题的核心思路的把握。', 1780933849, '1', '0', '14', '');
INSERT INTO `douyin_aweme_comment` VALUES (279, '52200511413', 'MS4wLjABAAAA9zyHdyW4ZyeZdz0bvVTH8lD4xWNlQG9s4ocV9WI7J5M', '178922139', '', '记性好的很', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_okIYK7EKLDPfyeDpCKAnIAABEFBbAC9A2QAYDf.jpeg?from=2064092626', NULL, '江苏', 1780981887183, 1780985442199, 7649215579585266469, 7648939065064115465, '我个人观点，不喜勿喷，我认为这卷子明显的目的是筛选学神和伪学神的，直接将140以下的归为了一档不作考虑。 出题人有出题水平，且专业水平很高，但没有水平，不知道有没有人能理解。', 1780971788, '3', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (280, '1129917417267748', 'MS4wLjABAAAAK1GL1qtvVzJDIWbKYrLtHO5G0meJ0H-lOI7GPVTW4V0QLG_oz85T6Ck-P5zscfdR', '2169866509', '', '猴哥儿', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oMewAifDNIos9QpApZSMDYZjECIAtEJAFAAHQg.jpeg?from=2064092626', NULL, '四川', 1780981887190, 1780985442236, 7649107176643986225, 7648939065064115465, '早都看出来了，最近几年老有人说数学课本改版后有问题，搞的他家小孩都学不会了，还在惦记以前的老教材。我在三四年前帮我侄女辅导数学的时候就发现了，现在的教材没有总结的公式，只有陈述。所有的一切都要靠自己去归纳总结。以前的课本会直接告诉你长方形的面积公式是：长*宽。现在的课本是一大串的描述。告诉你长方形和正方形的面积是它的边长的乘积（就是类似于这样的一段话，或比这段话更加冗长的一段话）所有的公式或者一些口诀都是一段话，或者是好长一段话，需要学生自己去总结。刚开始觉得怪怪的，后来才觉得有些其实已经饱和了，国家更需要的是有思维的人。而不是刷题机器。', 1780946552, '5', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (281, '808837629084624', 'MS4wLjABAAAAH6n1bP2LNz8isEfdg-ITPSUQsigQJLFyEp19gXodP38', '3785926058', 'naibabuzheng', '奶爸不正经', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_a9c1006a038b4eab9f1de00f6222ccfb.jpeg?from=2064092626', NULL, '宁夏', 1780981887197, 1780981887196, 7649075854563803962, 7648939065064115465, '评论区的醒醒，最后这道题是给国家选拔高精尖人才用的，其他的题靠刷还是有希望的。这道题会不会做并不影响你家娃是读普通本科还是读大专，只会影响去清华还是去交大[我想静静]', 1780939259, '0', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (282, '1169480032719971', 'MS4wLjABAAAAx3Yg8AvaZalz18TLUbNc6P9T7_HQd37ZaG15utyeRIp2n8vHOBVfkFcoSqnWCD9h', '3488889667', 'JHNR', '江鹏｜以史观世', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oMAayHxteyhlCDA7C9zl26fpAQL0gAEEl8PAIA.jpeg?from=2064092626', NULL, '河北', 1780981887206, 1780981887203, 7649243065378587407, 7648939065064115465, '这次是最公平的数学试题，杜绝了那种靠刷题上位的勤奋，但没天赋的学生，数字本来就是靠的天赋，靠勤奋和努力刷题，得来好成绩是不可取的。这就是为什么，这些年以来我们的数学，在全世界都不咋样的原因。所以这个改革方向很正确[赞][赞][赞][赞][赞]', 1780978187, '1', '0', '7', '');
