INSERT INTO `douyin_aweme_comment` VALUES (291, '1242867317086284', 'MS4wLjABAAAAIrAQfLpMfCI7OGQFDGkyvO0wagdpzkC18OJrb2bghvs5d3pKtMb1mL5dKtcLSRlq', '98924479741', '98924479741', '诉梦辞', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ooFYjADqBAhVEW1AEfjWA9ZEeWFfI4OAAG3wED.jpeg?from=2064092626', NULL, '天津', 1780981903719, 1780981903718, 7648974333851927333, 7648964126915497254, '当有勇敢的人站出来了，就不能后退，一定要壮大声势，开团秒跟。[躺平][躺平][躺平][躺平][躺平][躺平]坚决不同意性年龄定在14岁，建议改成18到20周岁之后，坚决和我素未谋面的姐妹们站在一边[躺平][躺平][躺平][躺平][躺平][躺平][躺平][躺平]因为我是女性，我也是个女孩，所以不能沉默！', 1780915619, '127', '0', '1251', '');
INSERT INTO `douyin_aweme_comment` VALUES (292, '4146950069037575', 'MS4wLjABAAAAIJIMcN0CAjyLIhLkrTFONEE6OialhQasYvp39c2VJDsy5vGNlL9f9VmFgddY7ORe', '2830411481', 'l740518211', '吃过饭', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_ccc5e762615c1d070dc771649c46d0a7.jpeg?from=2064092626', NULL, '广东', 1780981903728, 1780981903727, 7649059493276681018, 7648964126915497254, '明明是大家的共识，却需要借用高考这样的大事来发声，所以这样的困扰是真的不被看到吗', 1780935447, '1', '0', '71', '');
INSERT INTO `douyin_aweme_comment` VALUES (293, '67951215396', 'MS4wLjABAAAA19YPFUBOeC3EhRdOWKhtxSek0r1KKE9nSdlHdcshYwc', '368651648', 'Y10398510', '菲', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_e5fcaa2281d46d5d323f93ccf6de940f.jpeg?from=2064092626', NULL, '山东', 1780981903735, 1780981903734, 7649068613572051749, 7648964126915497254, '如果不能保证未成年的安全，那就不生小孩，降低国家生育率', 1780937571, '1', '0', '197', '');
INSERT INTO `douyin_aweme_comment` VALUES (294, '2936170576615491', 'MS4wLjABAAAAPjQGD7QcfcAlZjUP3GMi-MnHsp3lxme_vTeSP3E8UdyI5eqSqdHv8lBBwAl9hfDw', '54634644483', '54634644483', '逐江舟', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oUCoNAAfTCBNJtd2EvFEAGDeBbA726AIESfqEU.jpeg?from=2064092626', NULL, '海南', 1780981903741, 1780981903740, 7649029400214635327, 7648964126915497254, '女孩子14岁——①电瓶车骑不了；②驾驶证考不了；③玩游戏还有限制；④去不了酒吧ktv各种娱乐场所；⑤酒店不能自己一个人住；⑥连网吧也去不了；⑦烟酒也不能买；⑧14才刚刚好可以不需要成人陪同自己坐高铁；⑨去医院还得挂儿科；⑩去医院还得家长陪同；⑩法律上14周岁还属于限制民事行为能力人……但是14周岁却可以有性同意，我是女性，我不同意，绝不同意！坚决反对！！！', 1780928439, '16', '0', '591', '');
INSERT INTO `douyin_aweme_comment` VALUES (295, '2969143702727876', 'MS4wLjABAAAAysB_rPC3YvyWA7G1a5FiYnvDWDCKY64PjxKJ6Dkkc1nE0Q6C2lx1YACDcam3PgVU', '21499361002', '21499361002', '仚屳屲冚', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oMegOoUXAGjAKzNo95GCAh7OaEQnIAFxAEAmfD.jpeg?from=2064092626', NULL, '陕西', 1780981903749, 1780981903748, 7649065026319647525, 7648964126915497254, '全员复诵！我是女生，也曾是女孩，我曾经14岁过！不懂一个14岁的小朋友她能懂什么？这个年纪是懵懂的，是不知道保护自己的，十四岁怎么能允许有性同意？\n 14周岁——①电动车开不了；②驾驶证考不了；③玩游戏还有限制；④去不了酒吧ktv各种娱乐场所；⑤酒店不能自己一个人住；⑥连网吧也去不了；⑦烟酒也不能买；⑧14才刚刚好可以不需要成人陪同自己坐高铁；⑨去医院还得挂儿科；⑩去医院还得家长陪同；⑩法律上14周岁还属于限制民事行为能力人……但是14周岁却可以有性同意，我不同意，绝不同意！坚决反对！！！.', 1780936736, '1', '0', '128', '');
INSERT INTO `douyin_aweme_comment` VALUES (296, '7545509632485246009', 'MS4wLjABAAAAen9uFTjpcT04W7MUx-Vs5kYqhTBrLYYdE-VwOgYTd4qrcSR58GIozqxXN5kiDXgD', '34076500821', '34076500821', 'SZ', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_c62669a7f7d2706d644aed66b12673ea.jpeg?from=2064092626', NULL, '湖北', 1780981903755, 1780981903754, 7649059900648014611, 7648964126915497254, '42岁的我，体制内，正在努力，如果有天，我能走到更高的位置，一定为女孩子和女人们发出更多声音！！！', 1780935542, '7', '0', '278', '');
INSERT INTO `douyin_aweme_comment` VALUES (297, '54238611717', 'MS4wLjABAAAAJog1iG7CoiyEkzb29h0-Kqz64VDMaEcj_Pw2kbLjaUg', '1507333181', 'songbantaoxing', '松坂桃杏', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_o06VEDiHA8eQ5yklEABAIfJ299qwbEAAAWiBfM.jpeg?from=2064092626', NULL, '江苏', 1780981903763, 1780981903761, 7649210538296001337, 7648964126915497254, '这不仅要要求提高性同意年龄，还要提高性教育意识，了解疾病的危害，完善性教育，自尊自爱提高每个人道德和价值观世界观[捂脸]（还有发声不是为自己是为所有人民不要分性别也没有歧视）', 1780970614, '1', '0', '52', '');
INSERT INTO `douyin_aweme_comment` VALUES (298, '3201411273726125', 'MS4wLjABAAAAZ8zi3hDNAh6fvrgQpp34mvPbkywxlq8VXsfK8GWoOelKDgk4XJPzFGlZd2JPYRlw', '60805370634', '60805370634', '柴和菜', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_fb5852c4b78442cb994286855ebc5624.jpeg?from=2064092626', NULL, '辽宁', 1780981903770, 1780981903769, 7649250688417088314, 7648964126915497254, '这个女生是我\n我重申：建议将我国刑法中性同意年龄由14周岁提高至18周岁，全面保护14–18岁未成年人免受性侵害，防止成年人利用年龄与地位优势诱骗、胁迫未成年人。', 1780979962, '0', '0', '39', '');
INSERT INTO `douyin_aweme_comment` VALUES (299, '105028374280', 'MS4wLjABAAAA4IYCfQR0_zFKgeR4ngqVqFT1-Zvl3AKKzQ_tBm7Kiks', '1787607897', 'TtT11112222333', '九亿男高的梦', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_8fa260abd6747d787ee8a8052fea9bbd.jpeg?from=2064092626', NULL, '山东', 1780981903779, 1780981903777, 7649062992151593766, 7648964126915497254, '劳动法那个真的希望赶快实现 在药店上班明天因为店长去开会培训 我要在七点半上到晚上九点半 没有加班费没有双倍底薪 后面也不会补我的假期 今天因为店长开会我在十点五十上到九点半和全天没区别 店长之前帮我顶过一个班 昨天正好是换他班我上了个全天 前天我上的晚班我感觉我要猝死了', 1780936261, '8', '0', '563', '');
INSERT INTO `douyin_aweme_comment` VALUES (300, '3705786962550458', 'MS4wLjABAAAA3kJpkk9Y3_CEHPhWMGNPv6R6RCrzGGIHpam5U9kAcNla7RnWO1eEajBiNnc01Osn', '25016212211', 'Jay_Lee77', '7-', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_233a4e6134f7c09a2e4a1220e90496dd.jpeg?from=2064092626', NULL, '甘肃', 1780981903791, 1780981903788, 7649074943019467569, 7648964126915497254, '“如果世界全是女生的话会怎样”\n“那我睡大街都会有人给我盖被子”', 1780939045, '7', '0', '88', '');
