INSERT INTO `douyin_aweme_comment` VALUES (302, '81222466780', 'MS4wLjABAAAAj3i_7NVeItFcxvJi7qzyM1cgyo5N5ujCGswdNMbk5DA', '1372232442', '', '退休得以解忧', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_5ea2b92d407416db5a548fbea55857bd.jpeg?from=2064092626', NULL, '上海', 1780981903811, 1780981903809, 7649068126618288955, 7648964126915497254, '拒绝挑起男女矛盾，我是男性，我也赞成提高性同意的年龄，两性应该是互帮互助而不是对立！！！[抱抱你][抱抱你][抱抱你]', 1780937458, '2', '0', '149', '');
INSERT INTO `douyin_aweme_comment` VALUES (303, '131548230205048', 'MS4wLjABAAAArJT2wYRTicIY0ws9w7YbCqwgyLwGTHKp77ydONXIe68', '3777010285', 'LQY19451129', 'Tina Wei', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_owZneCDfNAKAwAk8EAARDb6WC2P1lIAgvA39gw.jpeg?from=2064092626', NULL, '土耳其', 1780981903828, 1780981903824, 7649058552351048494, 7648964126915497254, '真担心说提高性性同意年龄到18岁的女孩被网暴', 1780935227, '12', '0', '277', '');
INSERT INTO `douyin_aweme_comment` VALUES (304, '101223239981', 'MS4wLjABAAAAde7Fz3myuQcNCSXu5qXR6fpTvSN_laohqutg65IfX7A', '1137689065', '', 'G👻↘', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_o0AJWbDeFA7fBFGNA7xsAEKBP93IQ8AfgShjAE.jpeg?from=2064092626', NULL, '河南', 1780981903843, 1780981903841, 7649042693376869179, 7648964126915497254, '性同意14岁 一个初中生 未踏足社会 处于义务教育阶段 人生观价值观还未完全形成 国内对性的知识普及较少 根本不了解自己的身体到底怎样同意 我同意调至18岁 14岁处于发育阶段 任何的伤害都是不可逆的 青春期的身体变化', 1780931534, '1', '0', '136', '');
INSERT INTO `douyin_aweme_comment` VALUES (305, '85579326367', 'MS4wLjABAAAAvFPW35K2Eg2ovd30Xsszi7NPzcTFhvJq1BSNGeJTRB0', '197958494', '', '旺旺宝贝', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oEELAzzIfvQj8AOkAPAg2fBLZeD7e8D0CGUIAV.jpeg?from=2064092626', NULL, '广东', 1780981903853, 1780981903850, 7648996804017013541, 7648964126915497254, '我被女性生下来，我是一位女性，我是女人，我曾经14岁过！一个14岁的小朋友她并不能彻底明白性同意意味着什么，也无法承担随之可能产生的后果。十四岁怎么能允许有性同意？！14周岁，①电动车开不了；②驾驶证考不了；③玩游戏还有限制；④去不了酒吧ktv各种娱乐场所；⑤酒店不能自己一个人住；⑥连网吧也去不了；⑦烟酒也不能买；⑧14才刚刚好可以不需要成人陪同自己坐高铁；⑨去医院还得挂儿科；⑩去医院还得家长陪同；⑩法律上14周岁还属于限制民事行为能力人…但是14周岁却可以有性同意，我不同意，绝不同意！坚决反对！！虽是复制粘贴的，但是这也是我想说的，代表我本人的意志！我曾经14岁过！不懂一个14岁的小朋友她能懂什么。14岁不能工作，连参军报国都不行！怎么就能允许有性同意 ？？！!但是14周岁却可以有性同意，我不同意，绝不同意！坚决反对！', 1780920850, '1', '0', '247', '');
INSERT INTO `douyin_aweme_comment` VALUES (306, '1502366381902464', 'MS4wLjABAAAApksOkI0F7EMtId8CEunyMrlPTWGpOTDuqdlZ8VmCqcQXq7p_tDdUtFB_rLV-rqez', '48751955702', '48751955702', '抖音精选官方账号', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_c0e5aad3548629d5e69f3104afa86d12.jpeg?from=2064092626', NULL, '北京', 1780981909732, 1780981909730, 7649212034646655770, 7649041458552458496, '如果高考作文以“你”为题，会写成如何？ 长按下图识别二维码，或上抖音精选搜索#抖音精选人生作文生成器 ，生成专属于你的“人生作文”吧！[考运爆棚]', 1780970962, '8', '0', '82', 'https://p11-sign.douyinpic.com/tos-cn-i-p14lwwcsbr/776705259683484c8218a86cde845dfe~tplv-p14lwwcsbr-7.image?lk3s=7b078dd2&x-expires=1781002800&x-signature=mfVBq2gIE2eqx2VNJQgGDZ%2Fb4TU%3D&from=2064092626&se=false&sc=image&biz_tag=aweme_comment&l=20260609131149036C42180E8FBA097801');
