INSERT INTO `douyin_aweme_comment` VALUES (310, '97674219700', 'MS4wLjABAAAA5TIK_1dW2QRJzpWyV3yJg9h5fOZvQizfCX3FnPZYq9Y', '922662416', '', '阁楼上的疯小孩~', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_2406600057f9034f06be7.jpeg?from=2064092626', NULL, '陕西', 1780981909766, 1780981909765, 7649189680004629297, 7649041458552458496, '我真的很惊呆现在的学生，讲文天祥聊到崖山之战，学生竟然说没学过[绝望的凝视][绝望的凝视][绝望的凝视]讲张衡说到候风地动仪，他们也说没学[绝望的凝视][绝望的凝视][绝望的凝视]', 1780965757, '3', '0', '23', '');
INSERT INTO `douyin_aweme_comment` VALUES (311, '68157187209', 'MS4wLjABAAAAgfIJJKed6NNwulqzyX9e0klxp7NAyBxfShRixuSt-Ys', '365415410', '', '执手相看泪眼', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_7eff96ec6c33a0d6b03d65c37ac6a1d1.jpeg?from=2064092626', NULL, '浙江', 1780981909776, 1780981909774, 7649128178364433189, 7649041458552458496, '陆秀夫本来庸庸碌碌一辈子就过了，死后可能还会被安排在秦桧一桌，可是当他背着赵昺跳下去的那一个，他在岳飞文天祥那桌坐稳了！中国人就是这样的，你可以没本事，可以不出众，但是到了关键时刻民族的血脉就会觉醒！', 1780951443, '2', '0', '8', '');
INSERT INTO `douyin_aweme_comment` VALUES (312, '95834091158', 'MS4wLjABAAAACT63O__LcUTe2kZrX_p211gpRChf3pa5jjaQ8IW9xk4', '613192595', '', '摆烂的多肉涛涛', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_26e100004593d73b0fca6.jpeg?from=2064092626', NULL, '泰国', 1780981909786, 1780981909783, 7649059581243900699, 7649041458552458496, '阿姨说的我好像都学过，或者自己看到过，但是穿不起来。阿姨这么一说，一切都连贯上了！不光要学习，还要理解，吃透', 1780935468, '1', '0', '42', '');
INSERT INTO `douyin_aweme_comment` VALUES (313, '76355722374', 'MS4wLjABAAAAYWtidifTunFLYa3mup0U3wINWphm-JcaIibRvpsj9DA', '911650359', 'VIP16661666', '好运来好运来', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_4d1672451235c86ce596dfea1e94841b.jpeg?from=2064092626', NULL, '北京', 1780981909794, 1780981909792, 7649061479770538802, 7649041458552458496, '如果我写我就写春晚，写春晚变乏味了，想知道为什么吗？因为之前纯搞笑只有华人、华侨自己看，现在是全球直播[微笑]不能只有搞笑了，要彰显祖国实力，彰显民族特色、团结偏文艺了，不搞笑了，可是那证明祖国强大了[微笑]不搞笑我可以不笑，但是我自豪[赞][赞][赞]', 1780935911, '3', '0', '30', '');
INSERT INTO `douyin_aweme_comment` VALUES (314, '111057752334', 'MS4wLjABAAAAPf7B7BKVz8Ad90ii4xU2CC3MYcaoH2-Hxh0sJ9AWFvo', '3806957024', 'dy9qxeakvxvp', '丫头宝贝', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_c6effa12aaa04ee5850461b05f2d852b.jpeg?from=2064092626', NULL, '贵州', 1780981909805, 1780981909801, 7649232937686876970, 7649041458552458496, '我想到的是时间，小时候对时间没有什么概念，感觉时间是白天和晚上，白天像缓缓移动的蜗牛。一个夜晚可以那么长，长到能做好多好多梦。那时候，时间像根可以随意拉伸的橡皮筋，总也用不完。\n\n长大些，觉得时间是春夏季冬四季，它们突然长了脚，开始小跑。你开始觉得它不够用，想要抓住它，它却像水，从指缝间溜走。课间十分钟永远不够玩闹，暑假也过得飞快。\n\n后来，时间变成了去年，几年，明年，它们仿佛生了翅膀，在身后不停追赶。你第一次感到慌张，开始理解“光阴”的含义——那些光一样抓不住的、明明存在却无法停留的东西。你学会看手表，学会赶时间，学会在日历上画格子。\n\n现在，时间安静下来，变成了昨天，今天，明天，它们是你掌心的温度。你不再追赶它，而是与它并肩而行。你知道每个日出日落都是新的，知道有些东西需要时间慢慢熬煮。你开始懂得——时间不是流逝，而是积累。每一个今天，都是昨天种下的明天。', 1780975829, '0', '0', '31', '');
INSERT INTO `douyin_aweme_comment` VALUES (315, '58660816176', 'MS4wLjABAAAApBlUvKdAlWBgLjU5tDdT1LgCyJGsb54JZVG8G8o8lrI', '115701828', 'LNW2012528', '薇娜~', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ocgfGGbYQAgLP3ADoTfI6ewAVIA2AALao3K2ke.jpeg?from=2064092626', NULL, '西藏', 1780981909820, 1780981909814, 7649086893946438457, 7649041458552458496, '喜欢我们院的院徽，远看像凤凰，近看是石榴籽。铸牢中华民族共同体[戳手手][戳手手]', 1780941828, '1', '0', '59', 'https://p3-sign.douyinpic.com/tos-cn-i-p14lwwcsbr/005dcc1c292b4a40b3288b91ac39130b~tplv-p14lwwcsbr-7.image?lk3s=7b078dd2&x-expires=1781002800&x-signature=Vuzsk6VCpApuMhzzTB5p7yWJwWo%3D&from=2064092626&se=false&sc=image&biz_tag=aweme_comment&l=20260609131149036C42180E8FBA097801');
INSERT INTO `douyin_aweme_comment` VALUES (316, '93625472178', 'MS4wLjABAAAAjGlzvhVRDCLdB0asrh5uybHDXqPRW5e1QcPpYZgUdzg', '714131883', 'Dd770114', 'mmmmm', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ow3gYPTlSU8AiNCAsEwAaA6Pg6AIIpSBi0YA3.jpeg?from=2064092626', NULL, '广东', 1780981909831, 1780981909829, 7649212546428191522, 7649041458552458496, '我选的是«母爱»\n曾经我认为母爱是不爱吃的鸡腿 是书包中的零食 是早晨的早餐 \n现在我认为母爱是在一个月黑风高的夜晚我发着高烧……', 1780971082, '11', '0', '129', '');
INSERT INTO `douyin_aweme_comment` VALUES (317, '81356190051', 'MS4wLjABAAAASP09jbqZ2O_Bd4c9fW3gwFt93Y_5JQfK5Z9J9PHt_7A', '184489973', '', '棍', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_23fd4000119ca191eebf3.jpeg?from=2064092626', NULL, '陕西', 1780981909842, 1780981909839, 7649228096784253733, 7649041458552458496, '虽然但是，俺宝鸡何尊里铭文“宅兹中国”的中国指的是人家洛阳。中国人的祖先就是华夏先民啊，那个能铸青铜礼器撰文铭字，也能锻青铜宝剑砍蛮族头颅，胜利归来后在渭河边唱关关雎鸠的生猛而又浪漫的民族。崖山赴死的不屈并不是中国人的核心精神，文武双全开拓进取才是，所以崖山后留取丹心照汗青的中国仍在。', 1780974702, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (318, '355866229618323', 'MS4wLjABAAAAmmkIZSIzCwT0dXVyNoEu2js8Rabi4_9sLi465CyFjuc', '2189217911', '', '10', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oYwApigy0EA4A0PyABE2DdafiACEeIvejA4Q4R.jpeg?from=2064092626', NULL, '江苏', 1780981909855, 1780981909852, 7649216884680852282, 7649041458552458496, '牛马，小时候认为牛马是动物，长大后发现是自己', 1780972092, '9', '0', '183', '');
INSERT INTO `douyin_aweme_comment` VALUES (319, '2062303909913422', 'MS4wLjABAAAAZ4SWWxHUy5H2PEwTn-lhO6j3VpES8gKCj16fT_vQRmgCyEakJuQN91qg1XmEHNRL', '2164198046', '64271454493', 'Han.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_c3bbdefb29bc6b030b6c6e490096e894.jpeg?from=2064092626', NULL, '广西', 1780981909871, 1780981909864, 7649154691243737914, 7649041458552458496, '小时候我觉得统一是冰红茶\r中年时我觉得统一是秦皇扫六合\r现在我觉得统一是两岸同胞同为一个中国', 1780957612, '2', '0', '19', '');
INSERT INTO `douyin_aweme_comment` VALUES (320, '96455644509', 'MS4wLjABAAAAmHzmNkRTcPLQB04Sp4N5Ysxlu0XmvcBbsgoR-mVexdA', '840105621', 'paoluolou', 'qun', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_d56c89bb70ebdd482df9345a17620e22.jpeg?from=2064092626', NULL, '湖南', 1780981909884, 1780981909881, 7649160171034100538, 7649041458552458496, '这个选题是真的大胆新颖，高度层次无可挑剔，希望考完后网上能公布更多的学生选题也是这个', 1780958888, '2', '0', '24', '');
