INSERT INTO `douyin_aweme_comment` VALUES (322, '88167201325', 'MS4wLjABAAAAJQZxw4XqbSgoijMx9Ink9mj4Nlrh1fsWGmiqMkpoi_I', '270549237', '', '一生所求 爱与自由', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_9bfdaded70474747add8aeccd6f47edd.jpeg?from=2064092626', NULL, '河北', 1780981909903, 1780981909900, 7649255650635891514, 7649041458552458496, '我写的是世面 小时候见世面是苹果手机 阿迪耐克 奔驰宝马\n长大了才发现 见世面是 览望山河壮阔 了解世界的多样性 体会大国崛起的表与里 理解中华民族伟大复兴的真正含义', 1780981117, '0', '0', '15', '');
INSERT INTO `douyin_aweme_comment` VALUES (323, '4226158568679780', 'MS4wLjABAAAA3lCKNoM31rIFchNPczQ9YEVYczJpulxuUy1qOnhYn4zBCOokmOxAFCJ5D6RrgC60', '2934531165', 'dydo1mwkdwko', '村里有个小方叫大仙', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_4a3ca3c62043423f86a643b8158fcdea.jpeg?from=2064092626', NULL, '上海', 1780981909912, 1780981909909, 7649074291670156090, 7649041458552458496, '我想到的是中华，小时候是铅笔，后来是牙膏，长大了是香烟，但永远不变的是我们的民族', 1780938896, '9', '0', '264', '');
INSERT INTO `douyin_aweme_comment` VALUES (324, '95953303574', 'MS4wLjABAAAAvCiEi7AzIoz9GBgNwEc8NTC8TGhZbLfIEknMP8lwtN4', '619978989', '', '🌈爱理财的鹏哥', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ogsZpAoDpCFvD8iFEAAhrAEfAEdifYcwX9ImBn.jpeg?from=2064092626', NULL, '河南', 1780981909927, 1780981909921, 7649190133383643919, 7649041458552458496, '从这个妈妈，肯定了我一点想法，作文能考满分的人，不一定是饱读各种诗书，但一定是中国历史刻在脑子里的人，所有题目都可以出口成章，所有题材都可以升华到家国情怀[赞]', 1780965864, '5', '0', '209', '');
INSERT INTO `douyin_aweme_comment` VALUES (325, '98431606279', 'MS4wLjABAAAAR2ncjzUVrFMF3xZ--X5vv0pk-GxLrMvsdRAU1xQqX-U', '934687653', 'VenTi22', 'VenTi', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oUfC2UFAEAEEAkw3stDhepIk9EApPS90kFfADW.jpeg?from=2064092626', NULL, '广西', 1780981909940, 1780981909936, 7649248063647449893, 7649041458552458496, '话说怎么知道自己高考作文满分的[发呆]', 1780979351, '17', '0', '30', '');
INSERT INTO `douyin_aweme_comment` VALUES (326, '3786348368245771', 'MS4wLjABAAAALJtF6rnYVKm137FMmwvrtgSpsWmX17FuSTbkQQ7thok7wI_Y_1Ec_JyGkvZNfEFL', '3767401003', 'beichengnanx51', '北城南下猫', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ocAA9FCapPclDyVA9fRCcoAxgCEVAAAIeozkEo.jpeg?from=2064092626', NULL, '湖南', 1780981915866, 1780981915861, 7648623097230803752, 7648498783520689454, '仓颉造字而天雨粟，鬼夜哭。 词语，自诞生起便被赋予了沟通天地、承载文明的使命。它们如琥珀，凝固着历史的泪痕；又如明镜，映照出时代的悲欢。在岁月长河中，有些词语的意蕴如磐石无转移，坚守着民族的精神内核；而有些，则在时代洪流的冲刷下熠熠生辉，焕发新生。对我而言，“妈妈”这个词语的蜕变，便是一场个体生命与宏大时代的交响。那是一个狂风暴雨的深夜，我妈背着发烧的我……', 1780833840, '4', '0', '34', '');
INSERT INTO `douyin_aweme_comment` VALUES (327, '96924360212', 'MS4wLjABAAAA6vbmejE2vcicuPsbnDOT9Hki-mjjsxhj1EsBUlOa0B4', '828101974', '', '🌈太_医', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_osOgqfOjAKuAzmNo9lICAdyz6EI6EAFPAAADfD.jpeg?from=2064092626', NULL, '山东', 1780981921762, 1780981921759, 7648965654062252854, 7648530295670922930, '好喜欢他的话：\n①见过世面以后心就静下来了.\n②感受到人与人之间的差距，就释然了，自己不太适合这方面，就去找适合自己的方面。\n③不要去跟别人比分数，比赚得多少，去找到能让你开心的生活就好，吃的开心，晚上睡好觉，不要去跟别人比，他在这方面做得好，他也有他的烦恼，他过得未必有你开心。', 1780913598, '19', '0', '329', '');
INSERT INTO `douyin_aweme_comment` VALUES (328, '1629898834720429', 'MS4wLjABAAAAQh6YxsFfleKnk6nvszOQbgHoHd1JEkG8P3Fd7uKYXD799UfDlCDmCKablve9umsg', '57013016912', '57013016912', '心灵首富写字', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oM7ApDieAEBvRzAAXaAwv4ij0iIZeLIEnA0JVC.jpeg?from=2064092626', NULL, '广东', 1780981921782, 1780981921779, 7648691052522308401, 7648530295670922930, '我严重怀疑人大附中给学生安排了心灵成长课程，从这个孩子的分享中我感受到：他精神富足，灵魂有趣，内心充盈，思想升华，心态乐观，积极向上的人生态度！这是我38岁才获得的无价之宝，其中花了学费和时间。本校家长看到我的评论，确认一下。', 1780849663, '17', '0', '188', '');
INSERT INTO `douyin_aweme_comment` VALUES (329, '575736168325155', 'MS4wLjABAAAAo_gC4wq2BTzRj7jkUIEUitRvJh2VR9w6jXqDqT_0mOs', '2329053878', 'langmanwenxi93', '💕浪漫温馨  💕', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_b1da318692b5d19c5f52730188c19f73.jpeg?from=2064092626', NULL, '山东', 1780981921794, 1780981921792, 7648569010657608500, 7648530295670922930, '这个男孩的谈吐说话真的是一个心态摆的特别正确的人生价值 他的父母一定是一懂得教育和孩子好好说话 父母感情特别好的家庭 才会有这样优秀的男孩。这才是一个从高考走向社会的正确路线👍👍。不和任何人攀比和炫耀。。。。', 1780821247, '1', '0', '109', '');
INSERT INTO `douyin_aweme_comment` VALUES (330, '2186301398061679', 'MS4wLjABAAAA4nYu1VI7UHrF_KGocvx4ZsCZNExQNFeJRDWxbobsBFWdy-eZUvZRFC8MV9AsgxBT', '90873498660', '90873498660', '愿天下再无不公           ＼', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_1247bf38cfdf40d79b0e01ff69c3ee7b.jpeg?from=2064092626', NULL, '黑龙江', 1780981921808, 1780981921804, 7649011295183127296, 7648530295670922930, '其家长的素养和身价显而易见，这是三代人优渥的家境才能培养出来的孩子，而且他的家长情绪极其稳定。\n在东北的确很难培养出这种素养的孩子。', 1780924225, '3', '0', '14', '');
