INSERT INTO `douyin_aweme_comment` VALUES (335, '68098199084', 'MS4wLjABAAAAuE0h627i0okPKsucLMb5GjZ3e-62AvnoiH9qp9snDzE', '69475159', '', '尘～', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_43a5031139304935a4f41283a7d85994.jpeg?from=2064092626', NULL, '广东', 1780981921863, 1780981921859, 7648977116529230651, 7648530295670922930, '这些孩子不是有钱人就能培养出来的 总是钱钱钱，把钱看到了第一位，他们是真的很聪明的，不是给几个亿他就聪明，聪明是钱买不到的，只能说在物质上教育上会比穷人好很多，但是没有脑子也不行，', 1780916266, '0', '0', '3', '');
