INSERT INTO `douyin_aweme_comment` VALUES (337, '100159746652', 'MS4wLjABAAAAAL40MkLMV6g59_MN4zOi1txExCX2tMFCcWa2s8Dzrn8', '1254222607', '', 'Dreaming Youth', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_3d689ae340fb232b5836ebb1d410619a.jpeg?from=2064092626', NULL, '北京', 1780981921892, 1780981921889, 7649259045203379001, 7648530295670922930, '这是高中生吗？我很久没有觉得因为教育真的能改变人这么多', 1780981908, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (338, '71799158333', 'MS4wLjABAAAAdoea1VaucMYDIaeuLCaN3vWDwuRxPfP9fJibNtx9NeI', '189666227', 'yyds8199', '可是 雪', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_671cf42a65187d35a5764b8ab5120104.jpeg?from=2064092626', NULL, '浙江', 1780981921911, 1780981921905, 7648672077483983665, 7648530295670922930, '这个男孩是教育的真好 有理智而成熟的心境 18岁的年纪领悟到别人30岁甚至一辈子都做不到的豁达 越来越觉得教育的成功不在于分数 成就和赚钱的多少 而是无论身处何境都有面对的勇气和积极生活的态度', 1780845244, '0', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (339, '93161826326', 'MS4wLjABAAAAAzGlvmEfV_E74QVYM2eFEY8U3fGxvJ6zmuWjgIuH1yk', '3509391001', 'dyyrmen70y9e', '氧', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_13b850547c72486cbec90eeaff41c196.jpeg?from=2064092626', NULL, '江苏', 1780981921926, 1780981921920, 7648845794430419761, 7648530295670922930, '这孩子心理素质太好，适合外交官[比心]', 1780885691, '0', '0', '7', '');
INSERT INTO `douyin_aweme_comment` VALUES (340, '106530282453', 'MS4wLjABAAAAUdz6I7IJns-i3iAGJJwZyvQjvGlzngkx_TKwOwpNEp0', '2191206864', '', '平~安~', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oseiKAclQA5uAkhADKY3C9eCCHGbQIEAABggIn.jpeg?from=2064092626', NULL, '江苏', 1780981921935, 1780981921933, 7648624617166979874, 7648530295670922930, '他们毫无压力 底气十足 是因为他们生活的容错率太高啦，即使考的不好都能上到很不错的大学，生活也会很好，普通家庭的容错率太低啦，一旦考不好基本上下辈子也就那么回事啦', 1780834194, '0', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (341, '86548990208', 'MS4wLjABAAAAvS4c6LZXyWz8blDshd9WBdqUpRcvPjpdtSKy7DyMpJA', '206243389', '', '淘气🍊', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_5ace0020f610926b9156.jpeg?from=2064092626', NULL, '河南', 1780981921943, 1780981921941, 7648811626846864162, 7648530295670922930, '人大附中吗[发呆]有次见过他们学校研学还是啥来着，哇塞孩子们都是一身干干净净的白色校服，走过去都是各种各样的浅浅的香味，就觉得干净[灵机一动]还有他们的自信和青春张力，作为家长就只能感慨下真好呀[捂脸]', 1780877736, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (342, '2235720621894601', 'MS4wLjABAAAAQVZty1D7iQcD_B14G7Hk0DlDH_xxEo8Tv5VcicUcjIZJ1r9IAOE2Bj1e6CEhJqb1', '79667585620', '79667585620', 'charge', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o0Tg9IAxPAaAAAiWiHNEyEoRIPAaBgYBG1hHA.jpeg?from=2064092626', NULL, '四川', 1780981921950, 1780981921949, 7649050820865409841, 7648530295670922930, '首先这个孩子的原生家庭非常优秀，父母给他充分的自由，真正的爱和认可。父母本身就是一个非常巨大的容器，才能涵养出这样优秀的孩子。一个孩子就是父母的潜意识的显化啊，真的是一代人比一代人更优秀，我在他这个年纪的时候，还深受原生家庭的苦恼，但是他已经懂得向内求和知道人生的真谛。是什么了，嗯，感觉这个孩子非常有福报，嗯内心很平和，对，像禅修内观过的人', 1780933428, '0', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (343, '111289974739', 'MS4wLjABAAAAC4F-g7ZEe6rzjhwNpfzxjJkeFVuJgXx2O94NnDqDaNk', '2077632948', '', '佛渡有缘人', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oMoAZAiGmEBdr7AA2sAgfDiI03IcedaACA15OC.jpeg?from=2064092626', NULL, '云南', 1780981921958, 1780981921956, 7648605942753788718, 7648530295670922930, '境界很高、口吐的知识面非常广日后有无限的潜能。祝福所有的学子都有自己的归宿。[比心][比心][比心]', 1780829847, '0', '0', '10', '');
INSERT INTO `douyin_aweme_comment` VALUES (344, '97858912590', 'MS4wLjABAAAA2aXJBdBE3PU11TWAwXmMWUhI6sGRxSqWpGrnuxezhrQ', '887019475', '', '好物优选梁园', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_8b3a81b6fa87d45f1b2838bbdd2b9a0e.jpeg?from=2064092626', NULL, '广东', 1780981921966, 1780981921965, 7648649528317608761, 7648530295670922930, '这孩子不仅谈吐大方，表达能力也很棒，思想开阔，豁达这就是多读书好好学习的意义，说到老师不是工作，而是理想，[比心][比心]不愧是学霸，他的谈吐，他的人生观，价值观，遭遇高于我们中年人之上[赞][赞]说的真好，这孩子前途无量[666][666][666]', 1780839994, '0', '0', '17', '');
INSERT INTO `douyin_aweme_comment` VALUES (345, '73136775838', 'MS4wLjABAAAAjba8A-_LTSB24FnYFR-M_NIDtVGp6F__nESenvegE1g', '1002553411', '', '福慧连连', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_925d0fe964cd762b4cce0dc42313731c.jpeg?from=2064092626', NULL, '辽宁', 1780981921974, 1780981921973, 7648811342379549498, 7648530295670922930, '我高中时期，也十分热爱计算机，为了它，我废寝忘食，老师无数次的告诉我不要那么沉迷于计算机，我告诉老师我要为了我国计算机事业的崛起而努力奋斗！对了，客户端的名字叫《热血传奇》', 1780877669, '0', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (346, '63774114188', 'MS4wLjABAAAAg-8xljBjt-9QMFrRlCCWUODrjNbJ5o6pDQPYfETtMxI', '690855355', '', '隐身', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ogo95iv9rED4AC1EEpgwomDfFrfAACaADISmAd.jpeg?from=2064092626', NULL, '上海', 1780981921981, 1780981921980, 7648901247340364601, 7648530295670922930, '感觉现在这些小孩谈吐都特别的现代化，特别的前卫，一点都不落俗套，而且特别的有超前思维的这个意识。小孩子谈吐特别有独立的主见，对于现代社会所处当下的一些事实，有自己独立的这个思考和见解，而且对于未来的发展自己有一定的这个认识，挺好的，现在这个孩子。', 1780898601, '0', '0', '5', '');
