INSERT INTO `douyin_aweme_comment` VALUES (389, '3825954165888232', 'MS4wLjABAAAAG8ky4LE03KPUXxjdxTI4B0WXEWCsCihUQAuHWL7SFyhSXSTNHBMpd6suTDqYiCAj', '3778867529', 'dxhx77', '星77', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oI01AG5IMALyBWPeBA0XwaTkLH7e1ACxIQnEAf.jpeg?from=2064092626', NULL, '河北', 1780984450173, 1780984450172, 7648654681137267514, 7648541436875194495, '你们不要说哪科考砸了 完蛋了啥的 现在成绩还没出 万一你答的就是对的呢 就算是真的砸了 还有别的科目 看的是总成绩 就算总成绩也不是很理想 那又能咋样 专科还能升本呢 只要有肯努力的心气 怎么样都不会太差的 [毕业啦][幸运草][上岸]剩下的科目继续努力啊大家', 1780841193, '1', '0', '8', '');
INSERT INTO `douyin_aweme_comment` VALUES (390, '1139550789855623', 'MS4wLjABAAAAM0JGs3ZHEjwJcVaJNeEY1FrDZbHMLWqvOGwF_LqnjQmSueoTnjaoIg5c4nJjQUJP', '65148219876', '65148219876', '身在广东心在山西', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_c4243d5203a29c0cd9afbed2192d2211.jpeg?from=2064092626', NULL, '广东', 1780984450180, 1780984450180, 7648731994885964559, 7648541436875194495, '我快坚持不住了，我一个人出来到广州打拼，今年才19岁，全身上下就800块钱，然后找不到工作，来了一个星期全被黑中介给骗走了，我好累呀，明天就要进场了，我怕进场以后又是那种[流泪]', 1780859203, '2', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (391, '555710053629252', 'MS4wLjABAAAAxXbea15n6KzpAyH7AVmFb1358R4xCeSVetWmkTLUdhA', '80474833514', '80474833514', '宁月', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o8TCDfemAElNIOpJpAqgFCSKEh9qAAtAAAYAUA.jpeg?from=2064092626', NULL, '四川', 1780984450190, 1780985402361, 7648600325154865962, 7648541436875194495, '一亩良田，万亩花开[玫瑰][玫瑰][赞]\n我的～乙～肝～转阴了，今天也是我的生日[捂脸]没有一个人祝福我[抱紧自己][抱紧自己]', 1780828538, '26', '0', '33', '');
INSERT INTO `douyin_aweme_comment` VALUES (392, '96882724680', 'MS4wLjABAAAAjY5O03eTld7uwYLFhX1duyg6ROz0u3wP1c5BskTU_QE', '809770231', '', '河豚🐡', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_d75321fb1cad42d9b64f32793807b60e.jpeg?from=2064092626', NULL, '河北', 1780984450197, 1780985402352, 7648669560552227633, 7648541436875194495, '每年高考都能想起来，我爸在我高考的时候守了我两天，我在本校考试，老师嘱咐过家长，考试这两天不要见孩子，怕影响孩子心态。每次考完，我爸看见有学生出校门就赶紧躲起来，怕我看到他。考完去接我，我爸跟我说就考完过来了一趟，我妈偷偷跟我说我爸守了我两天[泪奔]我爸是个不善言辞的爹，惹我生气之后只会给我一罐杏仁露表达歉意，我还是好爱我爸[大笑]', 1780844658, '2', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (393, '100420625258', 'MS4wLjABAAAA28baupgqBn1EQ4EDTXGyyT_Xg-rz3ZCB6bz5Ae7zEx8', '1071442969', '2022.07.24cy', '梦·成', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oEIBfFTv1EA4JxDoQfvtA8AgEXXiif8KrH9A70.jpeg?from=2064092626', NULL, '四川', 1780984450204, 1780985402379, 7648990206515462961, 7648541436875194495, '考炸一科又能怎样，从小到大炸了多少次了，成绩不是终点，保持学习的心才是，你们的人生不会结束，22年考生路过[得意]', 1780919314, '2', '0', '7', '');
INSERT INTO `douyin_aweme_comment` VALUES (394, '97073199330', 'MS4wLjABAAAA3fgq3uOjpdLNtBOei7fMdbkU2Gv3_3GZd_bOBTZu0bA', '839906867', '', '罖亽', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_33cd819235df014057c89e6f6ca7a7ec.jpeg?from=2064092626', NULL, '四川', 1780984450211, 1780985402393, 7648637281712702234, 7648541436875194495, '各位考生们 这次没考好也只是没考好而已  那些考好了的 以后也一样过着普通的生活。这次的失利只是代表着以后需要走的路更多一点而已 并不是要面临死门了 放宽心 输一场不代表一直都会输下去', 1780837473, '0', '0', '76', '');
INSERT INTO `douyin_aweme_comment` VALUES (395, '1917193333506868', 'MS4wLjABAAAAFW9-HnS37z5S5Rnr2--nT_Fslxw-Q7DrySP7-qeMSMvcVd341mBAHE69jSG3mIyl', '3975118031', 'dyagbfjukjzw', '君君烘焙', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o0EAQGLfs1QI5GB7WwfTXAFNoAMDaHABAOmZeE.jpeg?from=2064092626', NULL, '贵州', 1780984450217, 1780985402415, 7649055371702027042, 7648541436875194495, '我高考考了380分，然后复读了，我是苗族高考可以加20分，第二次考上了贵州大学。毕业后考上了银行，拒绝了工作。选择摆地摊创业，现在在大学城做了14年生意。高考只是人生之路的一段小路，不是全部。尽力就好，努力向前，祝福大家[玫瑰][玫瑰][玫瑰]', 1780934488, '1', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (396, '2664804480713918', 'MS4wLjABAAAAYqFTc3GnV7aP57azhWSfzdrUDsrT_R4D08wl4xwQK5U-lILTsCbypiKFb19kwRJo', '3056946961', 'ZQzhaboom', '给我一瓶可爱多🎶', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_852e9f94361d241fcf9b7a59b71e3860.jpeg?from=2064092626', NULL, '安徽', 1780984450225, 1780985402342, 7648657022955881253, 7648541436875194495, '作为过来人，我想说的是第一天考的不咋样别灰心，我高考那年第一天语文87，数学67，当时心态炸裂了都，第二天考的还行，后来也是超一本线17分走的。', 1780841739, '2', '0', '11', '');
INSERT INTO `douyin_aweme_comment` VALUES (397, '350070724367764', 'MS4wLjABAAAA6b-1NHjMnYlzbk71lNMyiam4-XO1VlXbTUWBDsAzXuQ', '50636406343', '50636406343', '日落', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o4fvvrmGYEBF4LEIAQ5AqAAwNheA0PerDB7iEF.jpeg?from=2064092626', NULL, '四川', 1780984450234, 1780985402441, 7648832874812654355, 7648541436875194495, '如果活着不是为了快乐.那长命百岁还有什么意义[流泪]\n我乙~肝~转阴了，今天也是我的生日没有一个人祝福我[抱紧自己][抱紧自己]', 1780882683, '20', '0', '22', '');
INSERT INTO `douyin_aweme_comment` VALUES (398, '1068322672094599', 'MS4wLjABAAAAQLHu9qqyHua3rChs0bERqG8haooGONo6yD4RbW0WpDnwarmtSdJAv-0X4kVLOyMe', '2812401893', 'dykmisob61io', '黎吧啦²', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_okRZQ8YhXGAKz0AfAGLvJ7TAMBcgAEPhg1eeII.jpeg?from=2064092626', NULL, '贵州', 1780984450240, 1780985402291, 7648582304187417393, 7648541436875194495, '想要不同IP的高考加油！阔以满足我吗', 1780824342, '20', '0', '10', '');
INSERT INTO `douyin_aweme_comment` VALUES (399, '932040613311949', 'MS4wLjABAAAA_J_mbYFikm3hITrUJ6sjaWVwsTU7T7taABK4yaLTKfI', '68021791838', '68021791838', 'Fiee', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_57d0e6d7e2bd43dc97d273f7e15b80b2.jpeg?from=2064092626', NULL, '山东', 1780984450248, 1780985402425, 7649205166399423282, 7648541436875194495, '小时候因为没带红领巾给班级扣分感觉自己人生完了，初中因为没做作业被叫家长感觉自己人生完了，高中因为高考发挥失常感觉自己人生完了，大学因为考研失利感觉自己人生完了，工作后碰到解决不了的活感觉自己人生完了，可回头看，没带红领巾算什么事啊，被叫家长影响堪比鱼没有自行车，高考失常不影响我上岸编制。轻舟已过万重山，你在长大，你的人生永远不会结束。', 1780969366, '0', '0', '12', '');
INSERT INTO `douyin_aweme_comment` VALUES (400, '82488537762', 'MS4wLjABAAAA-1_ROYXff-8nLDm7LJhe5W2hCBmsAlBrqJVlXPbiD20', '2349978983', 'Are1002', '乘风', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_6d1c1967669e6b16841595461238d6a8.jpeg?from=2064092626', NULL, '四川', 1780984450254, 1780985402327, 7648980517077648147, 7648541436875194495, '大家都加油，我失败了。家里小农村，老爸16年去世，老妈只会语音不会打字，去年创业赔了挺多钱，今年出来也不顺利，在外面一个多月了没找到活干，两天没吃饭，饿的手发抖、太累了，刷到视频感概很深，分享出来。此刻没地方去在网吧角落里坐着充电。每当老妈问在干嘛做什么我都说我在上班了，好多问题我都敷衍而过，不敢说太多怕露馅，顶不住下辈子不来了', 1780917058, '2', '0', '7', '');
INSERT INTO `douyin_aweme_comment` VALUES (401, '694508584699374', 'MS4wLjABAAAAY5tEZSfFj4UOFeqyzljE-uNrBwgodb6tXY6PMIDOrmE', '3590527333', 'tianxinglan572', '生.升?', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oEAFAeVeCIgTLJA5EDGU7AlGgIxBOrAIfaEYIA.jpeg?from=2064092626', NULL, '福建', 1780984450263, 1780985402452, 7648589016635900709, 7648541436875194495, '现在的高考生有看过这个电影吗 我22 记得很小的时候看的🤔', 1780825905, '1', '0', '38', '');
