INSERT INTO `douyin_aweme_comment` VALUES (403, '3889451269892796', 'MS4wLjABAAAACcAtN9ofTv5GmxgREFssHTKHRdblyHu8De6rgYrnXhEBLf2AjsDf_Tm_RvQSzAaZ', '22902485687', '22902485687', '初十是只猫🐱', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oYoQaIAARArgAIABJgPPA6m6iwIXy9ADnCiiE.jpeg?from=2064092626', NULL, '江苏', 1780984450278, 1780985402305, 7648804281903203123, 7648541436875194495, '不知道为什么现在的孩子眼里好像都没有光了，特别是初高中的孩子，来我家店吃砂锅的初高中孩子，爸爸妈妈带着，几乎都是低着头默默不做声，好像很疲惫很累，每次看到我就很心疼这些孩子，有的老顾客的孩子我会安慰鼓励几句，真心的心疼现在的孩子，太累了[比心]', 1780876026, '0', '0', '14', '');
