INSERT INTO `douyin_aweme_comment` VALUES (437, '75260293042', 'MS4wLjABAAAA_gFGeWmhah9tG5Et-4C6b7OGh7su6sJ1OCHbxGo6d04', '121043018', '', '蓝绿色BG', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_c83e001cdeb14680ea5a.jpeg?from=2064092626', NULL, '辽宁', 1780984462006, 1780984462005, 7648645670593430282, 7648522682211781894, '这高三孩子的思维逻辑和语言组织能力，比一些该溜子本科的毕业生都强。现在真不是大学生找不着工作，是大学生也分369等。', 1780839423, '28', '0', '1012', '');
INSERT INTO `douyin_aweme_comment` VALUES (438, '1417741368819737', 'MS4wLjABAAAA5-P3ZbxE0GtKbLlsnw1Cjy1IBe1dnD8KU7CmtAXcNCRxdF2YVQ4SlXm4tPgGDrml', '71375754239', '71375754239', '66666', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_8bd144855be92ab951c7ac4c81797c8f.jpeg?from=2064092626', NULL, '尼日利亚', 1780984467711, 1780984467710, 7648730397887431482, 7647396113951406762, '我们高考那年，考前一个月数学老师突然人间蒸发了，因此全校师生疯狂研究我们数学老师的解题思路，高考结束后才知道，数学老师是因为嫖娼被抓了', 1780858829, '17', '0', '186', '');
INSERT INTO `douyin_aweme_comment` VALUES (439, '7487141933598573625', 'MS4wLjABAAAAV232Yf3wSRcUuRfFxOP9ixSCJV3pNOGg3JnCvbiMUDck02NwPaf6CjvF_HDfnnHe', '39313373445', '39313373445', 'U.u🥴', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_4b0e48f8e0fd4b022d7c857b78672faf.jpeg?from=2064092626', NULL, '广东', 1780984467719, 1780984467718, 7649269718579397403, 7647396113951406762, '没事，10年后00后10后崛起.他们都不生孩子[不看]', 1780984393, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (440, '102029406990', 'MS4wLjABAAAAKea4HG_ThVw4_A7O_S21wT2hDWvm3aVE7PLoZM2bdrM', '2113500900', '', '半生糊涂半生人', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_319c20000ed65e6174864.jpeg?from=2064092626', NULL, '江苏', 1780984467726, 1780984467725, 7648831482513326882, 7647396113951406762, '22年的高考数学那不难度的问题，是脱离高中知识范畴，有一道题80%以上的高中数学老师都不知道是问的什么？儿子平时成绩120+高考成绩98分，儿子同桌平时成绩和我儿子差不多，高考成绩59分，看到试卷三分钟后就当场崩溃哭了，儿子今天大学毕业了，他说还经常梦到高考数学的场景。', 1780882359, '5', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (441, '102716942986', 'MS4wLjABAAAA7QjG9siLRwKHDrADuAnJ4PuVCynjJF96DGzmeMSvY6c', '1245165885', '', '暗影之舞', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_1ea1327792f1d1e89a408e6d3ba181ce.jpeg?from=2064092626', NULL, '湖南', 1780984467733, 1780984467732, 7648941528097915685, 7647396113951406762, '我高考134分，从事的也是数学这方面的工作，看了一下最后这题，我个人认为最后这道题的第三问纯粹为了清北生出的，本来现在高考题计算量就很大，最后一题想要完整做出来没有半个小时以上的时间不可能，我都不敢想在考场上遇到这种题有多难受[呲牙]', 1780907980, '4', '0', '21', '');
INSERT INTO `douyin_aweme_comment` VALUES (442, '2291014845344259', 'MS4wLjABAAAAnnTA0aZsL0s8WhGZeDO0PVgH6V3ss2fPfuM_GXD8qY1BUm10cCb0L1aLhyj0Zz33', '2834143774', 'qhui2020', '山城锅包肉', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_423de71d622449be921d406ccdcae1aa.jpeg?from=2064092626', NULL, '重庆', 1780984467741, 1780984467740, 7648856064045810475, 7647396113951406762, '数学是我的恶魔，从小就不及格，高考150分我考了84分时历次考试中得分最高的一次，那年过本科线五分考上一所省属师范，后来终于不学数学了，我才迎来了人生转机，此后考研考博都十分顺利', 1780888504, '16', '0', '36', '');
INSERT INTO `douyin_aweme_comment` VALUES (443, '102141053757', 'MS4wLjABAAAAbymub0QcAzTsU-L78dtal5Fb5bNIes-3DPZb31ixCmE', '1451538225', '', '🍺微醺走余生🎵', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o4IwOcQiv4FaszQCEjAPEIBPAhAGIABB9AiLa.jpeg?from=2064092626', NULL, '广东', 1780984467747, 1780984467745, 7649229540691247910, 7647396113951406762, '现在是AI时代了，以前的高考模式淘汰了，靠死记硬背套路没用了。现在国家根据未来的发展要为高考改革大洗牌选拔人才了，需要有逻辑思维，理解能力，意思就是要脑子很灵活的一批专门搞科研的人才，不被AI替代[比心]', 1780975039, '0', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (444, '102433941560', 'MS4wLjABAAAALpnd_sY4Ga1k4qkJJqfS4PMbpOsSW8E06A-uUG_wgPE', '1228203537', 'YSCM369', '新疆网红小罐文冠茶张晋平', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oEAytyJfe0isDNAECiBHy9i8AuQYgA7EvUnAIA.jpeg?from=2064092626', NULL, '新疆', 1780984467753, 1780984467752, 7648869188325442354, 7647396113951406762, '特别是数理化，应该训练举一反三、触类旁通的能力，而不是海量刷题。回想起来，我上高中的时候，从来没有辅导班，仅凭课堂45分钟，做到了考试即第一，学习考试哪有那么累？[捂脸]所以我在想，是不是方法一开始就错了？[捂脸][捂脸][捂脸]', 1780891137, '1', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (445, '2260239326645160', 'MS4wLjABAAAATaSUJAi4HBqFDuzIqMtMKNlkta2AWvUJ69Tqw8BbSrve4zcFMpk3PRtOdIXD-mTv', '3699775150', 'dyssirk3qek6', '铁杆', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_fbaef667a2071f1a3bddad797a31df43.jpeg?from=2064092626', NULL, '湖南', 1780984467762, 1780984467760, 7648966870292644650, 7647396113951406762, '其实这道题就是給培训机构服务，让基础好的学生又要去培训机构上课了。国家培养人才的道路千万条，何必为难高中生。而且招收的清北生与顶尖985的学生最终去了国外。为什么美国与西方国家升学考试很容易？他们的科技不发达吗？这样考就是为难一线的数学教师。', 1780913880, '1', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (446, '93406408083', 'MS4wLjABAAAAzOp6R-oCZTp1tL7KkaJ57Ru3OQCXM-5JMrPb7M_P1H0', '376585103', '', '小悦大神', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_8647c42dda08ca870a86b5bf82e500f6.jpeg?from=2064092626', NULL, '江苏', 1780984467768, 1780984467767, 7648972592069690139, 7647396113951406762, '为啥要去研究最后一题呢，充其量研究第一问就行了，把普通题和有些难度的题都拿到分才是主要任务，最后一题天才会的自然会，不会的讲死了也不会，干嘛要去纠结最后一题呢，又有几个人在考场有时间去研究最后一题呢', 1780915213, '0', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (447, '3138455975758012', 'MS4wLjABAAAA7o4k6boO3S2mh4WK3b_3kAdyho0hjDpijOctmp7LM6o7n9P9HAX1mipSdkyRlD33', '38498628610', '38498628610', '郭多多', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_0adcd4f64875ab88358f47ff9a401e47.jpeg?from=2064092626', NULL, '北京', 1780984467775, 1780984467773, 7649050496749519650, 7647396113951406762, '有水平的老师都说这题出的好[微笑] 没水平押题猜题的才不满', 1780933352, '14', '0', '16', '');
INSERT INTO `douyin_aweme_comment` VALUES (448, '99407934789', 'MS4wLjABAAAA0sAq3KUBAWCniH4lSzI9hzzBGt09AR675Q4aS1j16Rw', '2266530838', 'dulingfengsa52', '独领风骚', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oYIAJFppKCAcEhDfQfbxAnAwEtTtcBuXRAZA9K.jpeg?from=2064092626', NULL, '湖北', 1780984467781, 1780984467780, 7649116308966408997, 7647396113951406762, '所以说数学是靠天赋的，国家筛选的就是要有天赋的人才，而不是一般的平凡人！时代在进步，国家要发展，只有有天赋的孩子，才能胜任国家高科技重任，我们理性接受吧！不要去责怪孩子………', 1780948680, '0', '0', '5', '');
INSERT INTO `douyin_aweme_comment` VALUES (449, '1754464737299502', 'MS4wLjABAAAAAE4VZOAsDRWI8pb8XG-t_qSQpXXVJ1SOcV377986pRAO5CfYnvomOgBDBJXB6Dni', '3371465496', 'dyt44dcj67mm', '桥哥SZ365', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oY41ADvBDE2heJ0AXXzzBKxKRChANieAiAAHIg.jpeg?from=2064092626', NULL, '四川', 1780984467788, 1780984467787, 7649124726611051291, 7647396113951406762, '高考是国家选人才，不是社会培训的结业考试，关键难题绝大部分人不会就对了。再难的高考数学也有不少满分[呲牙]', 1780950641, '5', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (450, '3180214167018366', 'MS4wLjABAAAA7iCl2dNKRZDSpOhxx7Ow9c0FuLBNOuLVMxaw1cpweQhGPC1y6YK-_-ZY1UCqD0B6', '25607883191', '25607883191', '李奉先（戒酒第二天）', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oEuA7E8gQQaABAB0kEYXeDnQgeMAWUAo1A82fq.jpeg?from=2064092626', NULL, '江西', 1780984467795, 1780984467794, 7648992710543704889, 7647396113951406762, '我老师很多年前告诉我了一句话，题目都在书本之外，答案都在书本之中[尬笑][尬笑][尬笑]', 1780919897, '0', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (451, '492176831947880', 'MS4wLjABAAAAr2vcnRNWFAnfC0_WhEXAD8K3Ma8p7SP5OBz4V24gwoM', '24517879859', '24517879859', '渝飘', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '浙江', 1780984467801, 1780984467800, 7648933345750237958, 7647396113951406762, '关键问题是老师教会学生真正的数学没有，老师按部就班混课时，学生能会什么', 1780906649, '14', '0', '30', '');
INSERT INTO `douyin_aweme_comment` VALUES (452, '69639208929', 'MS4wLjABAAAANULfsehTp3zc9vUTeZENpPRQC7gWk4JwNE8jNEXPubU', '152796262', 'KC8989', '郑州漫悦精品酒店官方号', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ok7haYAA9YxqAIABahPvAuh6iBMZYyA4q3iME.jpeg?from=2064092626', NULL, '河南', 1780984467810, 1780984467809, 7649058138666074938, 7647396113951406762, '这则视频分析了2026年高考数学最后一道题的难度，指出其核心难点在于“新”而非“偏”。视频的核心观点是，这道题虽然看起来无从下手，但完全基于高中知识点，旨在考察学生的数学建模思维和独立解决问题的能力。视频以此为鉴，提醒未来的考生和家长，高考数学已进入“考思维、考能力”的深水区，依赖套路拿高分的时代已经结束。', 1780935130, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (453, '101619043110', 'MS4wLjABAAAA-U_Xz5A1NBc4U1dpRAGsKCF_efj_V8foqiWBYZKOjx8', '1154187256', '', '快乐人生', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_a690777338394334860394871ac73345.jpeg?from=2064092626', NULL, '陕西', 1780984467816, 1780984467815, 7649269788343419684, 7647396113951406762, '这种摸式题高一就让学生学到见到这种摸式题，为啥要放在考试中见到', 1780984410, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (454, '1908358134892574', 'MS4wLjABAAAAdEJ2OFO0bgssCAng7gqWPNMBqQmsSxqXCigmnij6Lc2P0UZbQncoHwVJHAijiJ20', '3537280219', 'dy8rahpwacrs', '老汉推Che', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_fcd511d11b411013f1923960ad5914ed.jpeg?from=2064092626', NULL, '浙江', 1780984467823, 1780984467822, 7648789743216018217, 7647396113951406762, '这是未来的国家策论！数学是所有理工科的基础，从芯片研发到人工智能再到航空航天，哪一项核心技术的突破离得开数学底层能力的支撑，现在重视储备数学人才，完全是着眼长远发展的战略布局啊。', 1780872641, '3', '0', '5', '');
