INSERT INTO `douyin_aweme_comment` VALUES (529, '111006639238', 'MS4wLjABAAAA9nZ8GdKTgRweWa4FvtWyPog3S1XZTBi-z5HyDCzkLxw', '2070864316', '', '桥下流浪汉', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oItPANZAbyFjEgh8c1SfcA5zCaApmIezjLCAAA.jpeg?from=2064092626', NULL, '江苏', 1780985331822, 1780985331818, 7648973764542317346, 7648599264814636403, '我16年考研的时候，数二也特别的难，从来没有接触过这种难度的试卷。那一年考场上我冷汗顺着后背往下流，但我告诉自己，我难，别人也难。那一年我比自己正常水平低了30分，那一年数二的平均成绩比往年低了60分，我考上了985的研究生', 1780915486, '2', '0', '16', '');
