INSERT INTO `douyin_aweme_comment` VALUES (537, '2780030722113608', 'MS4wLjABAAAA3YS0hakX9CZpdOkq2MMEyCGu-T0tkLS69Ylz1VON4rmWkncVrwdbaGfHcgHGX0pF', '23341816349', '23341816349', '茶饮养生', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_3e8c114471c74a20b27ae9e80e074f4b.jpeg?from=2064092626', NULL, '重庆', 1780985342177, 1780985342175, 7649264434817352454, 7648995544622255406, '对于学霸来说：数学简单140+，数学上难度也能考140+；对于中等生：数学简单120+，数学上难度80分——100分。这种筛选方式让仅靠刷题或者通过校外培训辅导去顶流大学变得很难，数学是真的考天赋。', 1780983665, '1', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (538, '3521075253608835', 'MS4wLjABAAAA21qtSbnRhzar6CghgVSobDitVogMlvJKSS4pvlI4xGFc0HrUEmKArnRxRKAl2VsW', '85201209168', '85201209168', '渑池县崔书祥', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oUoTmOdezEY9ASBEi0Cw0XB4ibfAAC7AAIkwAH.jpeg?from=2064092626', NULL, '广东', 1780985342186, 1780985342184, 7649273414607602447, 7648995544622255406, '数学不是计算，是逻辑是分析，', 1780985254, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (539, '75580250991', 'MS4wLjABAAAAlMM_AQRrwIIb7QT2W8eQGrLmth0ESwydMzzW8YrOc1U', '377014851', '', 'Jing.T', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_009877cb9376b8a566a6e6f056c935b6.jpeg?from=2064092626', NULL, '广西', 1780985342193, 1780985342191, 7649250102222226225, 7648995544622255406, '人性最大的恶，就是在自己最小的权力范围内，最大限度地为难别人。', 1780979826, '1', '0', '0', '');
