INSERT INTO `douyin_aweme_comment` VALUES (541, '11995182053', 'MS4wLjABAAAAEJlH_6APFQQGrumtWf30IPruRwQwpi-QtGPaUSqsy40', '10599696', '', '蜀叔', 'https://p3-pc.douyinpic.com/aweme/100x100/8e550014d4fa856ae91c.jpeg?from=2064092626', NULL, '上海', 1780985342209, 1780985342208, 7649273563707065134, 7648995544622255406, '这就对了，非要带上语文英语，害了好几代人', 1780985289, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (542, '84647620354', 'MS4wLjABAAAAqr7RfNigPXHBhzI8QeqGArZDTimyNYdzJjISIe69ic0', '2095140181', 'z1095760181', '秦凝雪月', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_1b47a00004f5058280ff4.jpeg?from=2064092626', NULL, '广东', 1780985342217, 1780985342216, 7649232853103805199, 7648995544622255406, '国家缺高科技人才，而高科技是没有标准答案的，高科技是靠人类去创造的，去创新的，而这个前提是数理化要非常好，不是套公式做题，不是疯狂刷题考高分，这样没意义，需要思维逻辑清晰，领悟能力强，悟性高的人去靠科研。', 1780975809, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (543, '3096703665964750', 'MS4wLjABAAAA7-QQM3sdRSAyUKSGanGcQPv3BxluHdJqxR4yo4Lvw79vqBArlWFu1JYex2jq99qY', '57270841121', '57270841121', '邓赞禄', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oIf9EAiqj2aYCAeRE7CpI13CgAFJAmAQkQDCAE.jpeg?from=2064092626', NULL, '广东', 1780985342225, 1780985342224, 7649268813271335720, 7648995544622255406, '讲的非常对，数学好的人是非常聪明的，语文，英语好的人不一定聪明，', 1780984182, '0', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (544, '3087026080202212', 'MS4wLjABAAAANAx217Fum2OOx8bhVjDi_GWf-6rzNklReHa5oZsWAYq3AbzO21hdB-V8DmfaXlhh', '3448000428', 'jingyu0371', '飞龙', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_01be69fff47645f88dc78867383eb162.jpeg?from=2064092626', NULL, '河南', 1780985342235, 1780985342232, 7649239149770031930, 7648995544622255406, '说白了就是国家需要高精尖技术人才，需要的是天赋型的种子选手，而不是靠努力死记硬背的熟练工！', 1780977275, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (545, '2317424981186044', 'MS4wLjABAAAAdELkm2JOUOKAK08JJqFPqOeD7bRCXoSWZMbYOymD0Gr-fPd3TC7pXpy8EGV1yNDZ', '4011871689', 'bugufumeiyig84', '89个人一起', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_f7bb78f26a254aa098cafb369961ada0.jpeg?from=2064092626', NULL, '安徽', 1780985342242, 1780985342241, 7649230306096890673, 7648995544622255406, '高考难不难和被狮子追是一个道理，不管狮子跑的快还是慢，你只要比同伙跑的快就行。高考录取都是按全省排名来录取，试卷难和不难无关紧要，全省排名才是关键。', 1780975216, '0', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (546, '84133823537', 'MS4wLjABAAAAqw3JL6cP-H9tSXBSjVAaJeZY9CwEdgzexbv33Pa7ENg', '210758437', '', '花落的那一天', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oANylQeAAizgGGxh7UfnHEA4A7AXIgCDyHACmA.jpeg?from=2064092626', NULL, '湖南', 1780985342254, 1780985342251, 7649201013002814257, 7648995544622255406, '天天重视教育，关注孩子心理问题，上来就是给中等生一大嘴巴子，打掉了他们三年的辛苦努力，起早贪黑，自信心灭的粉碎，这届高三是犯天条了[捂脸][捂脸][捂脸]。', 1780968397, '7', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (547, '95415870016', 'MS4wLjABAAAAwraALHfSKRAnk38rOrDGOEW5t2xAGYYCdpN1m6mUIrk', '1715964055', 'xuweicheng59', '徐卫城', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oMuhsFBEAM9vAIzEECFnAUDDguD1AAzGfV4AEe.jpeg?from=2064092626', NULL, '山东', 1780985342266, 1780985342262, 7649273297449141038, 7648995544622255406, '时代的变革，你没有真本事一切都结束了，把更好的机会留给真正需要的人，造福国家，造福人民百性，造福子孙后代', 1780985227, '0', '0', '0', '');
