INSERT INTO `douyin_aweme_comment` VALUES (554, '3147247061045520', 'MS4wLjABAAAA2l4HDLyxa073Ma5AqG398pOQECm9hs4lmr9RWEgGxgZHRwB5zWaWnzYc9s3NEDjX', '64763306211', '64763306211', '梦中有你', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ooMdfQb2fIfcDkGCQkSA1NMTWN8AAIaABQZeAz.jpeg?from=2064092626', NULL, '甘肃', 1780985342326, 1780985342324, 7649256709768413993, 7648995544622255406, '再难也难不过2003年的', 1780981364, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (555, '63118814879', 'MS4wLjABAAAAW_lwgWK7qIfN2IXNkGnpaXEWxnpONNa_8tZhUPrxzCo', '35672681', 'M.eng99.', '🎈M', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_7e28f4e66b0789cfed97fcd2d04d175f.jpeg?from=2064092626', NULL, '江苏', 1780985348133, 1780985348131, 7648556933637718833, 7648498783520689454, '我们高考那年，考前一个月数学老师突然人间蒸发了，因此全校师生疯狂研究我们数学老师的解题思路，高考结束后才知道，数学老师是因为嫖娼被抓了', 1780818435, '1104', '0', '34790', '');
INSERT INTO `douyin_aweme_comment` VALUES (556, '2840738331103709', 'MS4wLjABAAAAIVYjSK8bX8YZ6Rf1aNp0qt89SX6j1Se5GchGeEpbOzi4LtDsAj0_kUFr7SDBOJlc', '3529020015', '5061041wl', '小拉', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_319a6000227f54d121f23.jpeg?from=2064092626', NULL, '四川', 1780985348148, 1780985348146, 7648568602031342394, 7648498783520689454, '既然在高考，那就选高考一词吧。。。 \n年少时解读高考，目光只停留在“结果”二字，将其视作划分人生优劣的标尺。历经岁月回望，才彻底改写了对它的理解。高考是公平的试炼场，它让普通的我们拥有凭努力改写前路的机会；但它从来不是人生的唯一定论。它教会我们坚持、自律与取舍，让我们在压力中学会扛事，在竞争中认清自我。它是青春的一个逗号，而非句号，真正的人生答卷，从走出考场的那一刻，才刚刚开始。', 1780821152, '2', '0', '23', '');
INSERT INTO `douyin_aweme_comment` VALUES (557, '66754735725', 'MS4wLjABAAAAg6Ykfjd05A81i_m9gIwgbnEvlMCK6a-waGQp-BxYJk4', '336900362', '', '专属于你的浪漫', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_owhA3AfEKgRvnw0NUICb9eAcA4EDFXAADgBgBG.jpeg?from=2064092626', NULL, '湖南', 1780985348168, 1780985348165, 7648580280218878762, 7648498783520689454, '理性与感性、AI 与人最大的区别就是，当数据确定让你把人的氧气管拔掉的时候，感情会告诉你，这个人养育了你、培养了你、陪伴了你，如果没有了他，你的家就不在了。', 1780823870, '0', '0', '22', '');
INSERT INTO `douyin_aweme_comment` VALUES (558, '108698457435', 'MS4wLjABAAAAWYD9zqDNxjMYEWzsJRDPgEzzkxDHbf7KeMMm-SNNXvA', '1821300371', '', '你的烂借口', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o4AA3IAamDyAY4X88WhsCfkAeATz6giNMEtAD0.jpeg?from=2064092626', NULL, '陕西', 1780985348177, 1780985348176, 7648554238683235131, 7648498783520689454, '那年，作文题目是 我的母亲 我看成 我的母校 了 考试最后5分钟我才发现，于是我就在作文的最后加了一句话 其实我是个孤儿，我从小就不懂什么是母爱，但我的母校教会了我知识陪伴了我的成长给了我温暖，在我的心里我的母校就是我的母亲[玫瑰]', 1780817807, '20', '0', '91', '');
INSERT INTO `douyin_aweme_comment` VALUES (559, '111347986195', 'MS4wLjABAAAAkmD4rUr_mlYdeNsil2uMPQbWsjv9h4g2zHP2RDUZwJk', '3982508708', 'Nata0009', 'Farrah', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_21989d3d2d8b2fbf74c337f2deb4a955.jpeg?from=2064092626', NULL, '上海', 1780985348184, 1780985348183, 7648526746997195579, 7648498783520689454, '作家金爱烂说：“人有，而 AI 没有的，是犹豫。”\n她说，当一个人倾听另一个人的烦恼与痛苦时，会有一种停顿。会咽下一些话，会迟疑，会反复揣测。\n那份犹豫里，藏着艰难支撑的体谅与关心。比起流畅快速的 AI 答案，人类粗糙的沉默，可能更能带来安慰。', 1780811407, '0', '0', '14', '');
INSERT INTO `douyin_aweme_comment` VALUES (560, '95077124018', 'MS4wLjABAAAAcCKdn0Hx7ahp3l9Bd07To8Us7AXQDXm01M6wp3lgU8Y', '589725858', 'LittleQHappy666', 'ღ桥屿', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_dfd031ca82b8a33ab690aac216e3a2e7.jpeg?from=2064092626', NULL, '福建', 1780985348192, 1780985348191, 7648581358490829617, 7648498783520689454, '犹豫，是人与AI的分界\nAI依靠算法与数据做出判断，指令下达便即刻行动，永远精准果决，从不会陷入纠结与迟疑。而犹豫，却是人类独有的特质。我们做选择时，会权衡利弊、顾及情感、考量他人，在得失、对错、情理之间反复思量。这份看似拖沓的徘徊，并非软弱，而是心底生出的共情、善意与思考。正是这份犹豫，让人类跳出了冰冷的逻辑框架，拥有了鲜活的情绪与复杂的灵魂。它隔开了机械的程序，也成为人工智能永远无法复刻的人性光芒。', 1780824121, '0', '0', '13', '');
INSERT INTO `douyin_aweme_comment` VALUES (561, '2819618786258800', 'MS4wLjABAAAA69p6siOTBY0e-JLK06NcaUOHbJcp9HPyEynypxv-ByIahMvmutJmGVq-QK-vnn4y', '51269695204', 'dy_knowledge', '抖音知识', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_010959c2c0c3a4a91c9d1f6cf67e005a.jpeg?from=2064092626', NULL, '上海', 1780985348201, 1780985348199, 7649269786158056207, 7648498783520689454, '预祝这位同学取得高分，最近抖音官方发起#抖音全民写作大赛，时值高考，重磅策划#重写高考作文 ，邀请评论区大家重写高考作文，历届作文题均可！带话题投稿即可！ [爱心] \n\n#抖音全民写作大赛，也邀请大家分享真实故事，捕捉情感微光，发现美好情感，活动期间带话题词 #抖音全民写作大赛 发布公开可见的相关原创内容，即视为参赛，就有机会获官方流量激励及最高2万现金奖励，还有机会获得签约和出版机会以及官方媒体报道哦，机会多多，详情可搜索“抖音全民写作大赛”！', 1780985009, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (562, '109570263623943', 'MS4wLjABAAAAqtxcheYg6kkb6ydlgDfC-U_r7RyfHC7Fo1TRSm2JecM', '2156930524', '', '我是当天才的料', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_6f06e3415a952079304cea13d5f2b301.jpeg?from=2064092626', NULL, '湖南', 1780985348216, 1780985348215, 7648619451260748553, 7648498783520689454, '我会写先生，小时候觉得先生只能用于男性，后面长大才之后对于有贡献的女性也可以称为先生，后面升华主题可以写时代的包容与进步和女性担当，最后结合青少年自身，打破时代偏见，书写时代新篇', 1780832990, '2', '0', '18', '');
INSERT INTO `douyin_aweme_comment` VALUES (563, '64370022134', 'MS4wLjABAAAA9jLsDjbwBv97aBPbDqyaTL3CPpsMRR3g9QtzG5BnGik', '872321075', '', '小七', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_24b1774386b7ef8b7b819a6cafb4044b.jpeg?from=2064092626', NULL, '湖北', 1780985348233, 1780985348230, 7648637142860137273, 7648498783520689454, '犹豫\n\n手指悬停在门铃上方一厘米处。\n按下，还是离开？\n他听见屋内传来拖鞋声，由远及近。掌心渗出细密的汗，指节僵在那里，像一只忘了怎么飞的蝴蝶。\n拖鞋声停在门后。\n一秒。两秒。\n他终于收回了手，转身走进楼梯间的阴影里。身后那扇门始终没有打开。\n风从楼道口灌进来，吹得墙上贴的小广告哗哗作响。', 1780837109, '0', '0', '13', '');
INSERT INTO `douyin_aweme_comment` VALUES (564, '68252561209', 'MS4wLjABAAAAHSYrvpM7fLUrs_xcb4ncOreS1_HDx4g891ALB4Ic0N4', '334477184', '', 'lois', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ogXPAi9Pi3TM2BXIpAhRpn8AA5aBAj9b4E1ZA.jpeg?from=2064092626', NULL, '广东', 1780985348242, 1780985348240, 7648543343547384634, 7648498783520689454, '人类和Ai最大的差距是什么呢？我想选择的是“温度”。时代步履匆匆，出行方式早已今非昔比：小时候雨夜生病，是妈妈冒雨背着年幼虚弱的我奔赴医院；如今一部手机，便能轻松叫来车辆。科技改写了生活，却复刻不了血肉相连的深情。[黄脸干杯]', 1780815271, '3', '0', '77', '');
INSERT INTO `douyin_aweme_comment` VALUES (565, '7517132888844944442', 'MS4wLjABAAAA8yQZOEgnlG4tXUtQi-ntG-AHKsfcbx3-g3hM8SQRTnA7QhwoEoVAa1YlUBG76vcm', '68340729781', '68340729781', '又是想死不敢死想活活不好的一天', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_osCbI8IGAzeJ4d2AiQReBjSQ3ALJe7AvC7Eg2g.jpeg?from=2064092626', NULL, '湖北', 1780985348258, 1780985348256, 7648569006811054907, 7648498783520689454, 'AI的犹豫是结巴，系统上的停顿，人类的犹豫是情感，可能是难过，委屈，痛苦，也能是勇敢，善良。', 1780821246, '0', '0', '52', '');
INSERT INTO `douyin_aweme_comment` VALUES (566, '105843452299', 'MS4wLjABAAAA6nYIeHJXkDOyVC3AmVAnFFxVOWN2N3JUu5fMm8iHCn8', '3514260192', 'dymh7esiaodw', '依然完美', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o4qsDfzeDE10Qr6tTAkAFIyZIR2eAAT8BC1AXe.jpeg?from=2064092626', NULL, '辽宁', 1780985354002, 1780985353993, 7649273708985287433, 7648947265968639247, '学的课本不考？那么还有必要学课本吗？', 1780985323, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (567, '59259775318', 'MS4wLjABAAAAA6NeXsyg_ra8_yPgQwsrGFo0i_NUYSOcY_ddscSMtSQ', '186832076', '', '鹿🦌鹿', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_1f46a451462ea98c947480bbe18aee09.jpeg?from=2064092626', NULL, '河南', 1780985354043, 1780985354041, 7649234000736797477, 7648947265968639247, '时代变了老师没变呀，还是这么教孩子的，你们先换老师啊，换新时代的老师呀，把之前的老师都换了[感谢]', 1780976076, '10', '0', '43', '');
INSERT INTO `douyin_aweme_comment` VALUES (568, '74756978337', 'MS4wLjABAAAAofS-japyNJQgSn3u1C8J_XfzXOIlj-fxRWeGSXQtujc', '1524099764', '', '依尚.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_c75a4a1f484b80e10715e218c9511d42.jpeg?from=2064092626', NULL, '广东', 1780985354052, 1780985354050, 7649229241583158059, 7648947265968639247, '要改变也要先改变老师！改变老师的教学方法！一上来就改变学生，大人都没反应过来，让孩子怎么反应过来！怪不得难哭了那么多考生', 1780974969, '5', '0', '9', '');
INSERT INTO `douyin_aweme_comment` VALUES (569, '75686898494', 'MS4wLjABAAAAxYshgwwWtvUEX5Dxqvmtpb0YfGQRUlOKn-rBwxXnbDk', '918561276', 'hwchjr', '花椒树下谈恋爱', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ocUe8xiCqA37vPeIAbJFJowEBfA2iEAaQEA05I.jpeg?from=2064092626', NULL, '四川', 1780985354059, 1780985354058, 7649164843249009465, 7648947265968639247, '人口越来越少了，看你怎么考，我儿才11岁他说他不结婚。', 1780959975, '2', '0', '23', '');
INSERT INTO `douyin_aweme_comment` VALUES (570, '92721869119', 'MS4wLjABAAAAxqDucfUQc_xFuE23j-PllrkMW4GZft2HpddKa_c8j8Y', '1103935358', '', '晶莹', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oEAtZjfODQDomckNAkFAo09H4CftpAEIEnw6Ab.jpeg?from=2064092626', NULL, '甘肃', 1780985354066, 1780985354065, 7649208596178649905, 7648947265968639247, '不是学的不考，考的不会的问题，而是学的是基础知识，而考的是如何运用所学的基础知识去解决问题，不是说仅仅考察把所学知识默写出来', 1780970163, '3', '0', '13', '');
INSERT INTO `douyin_aweme_comment` VALUES (571, '84227359425', 'MS4wLjABAAAA0G-MOsJ-hOrhP_QWyJDaxXJnMLttwJVqqFNSdOynu3Y', '847673441', '', '✿.梦已ོ成殇ꦿོ༊', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o8v0KAkeWCA6NEQpH5FfACg6418AuGIG9ADzAn.jpeg?from=2064092626', NULL, '湖南', 1780985354092, 1780985354091, 7649158948390339380, 7648947265968639247, '这是想毁了这一届的孩子，学的课本上的没考，考的课本上没学，知道用Al为什么不用Al教学呢', 1780958605, '2', '0', '21', '');
INSERT INTO `douyin_aweme_comment` VALUES (572, '1675302341720604', 'MS4wLjABAAAA1YkD4NyTsjgmisCtjZv1dW9vv7dWucxXbezZ2UjWqYXf-SvLc0LQGHum1n4X027R', '3618852030', 'jiandan63370', '简～～单', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_o4xE8FD17BJpAQAq1bEIufEAHA2geqAM2Rf6QH.jpeg?from=2064092626', NULL, '河南', 1780985354120, 1780985354119, 7649162895448720187, 7648947265968639247, '怪不得看到网上都说今年的高考难，原来高考的逻辑变了，以后拼的根本不是记忆力，是思维能力。', 1780959522, '2', '0', '20', '');
INSERT INTO `douyin_aweme_comment` VALUES (573, '3988643056720660', 'MS4wLjABAAAAEF_l_jPEy4mZXjfYst-YJRjM6UfO5g4OTYO1Cu1z4_CPOcHQApyfG77P31UGwRcg', '3399481488', 'yedegangqin8', '蓝莲花', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ooEAGpiAvCiAdg9YyHIABiiAeLBZzRAVGfySyD.jpeg?from=2064092626', NULL, '江苏', 1780985354142, 1780985354141, 7649194395615118099, 7648947265968639247, '这才是高考真正的内涵。能死记硬背的人，将被淘汰，会独立思考，创造性的人将有出路', 1780966856, '1', '0', '28', '');
INSERT INTO `douyin_aweme_comment` VALUES (574, '2071107324358308', 'MS4wLjABAAAACCRtOGZpHmEi2XpIK7WKJT6R86vEFYJ4bwL7Sck9_yNy1eHP_TsGt6kmfKq3ASrT', '3495298377', 'cenyanahihanpi', '心如水静🌹', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_e61016fc062a4e64a75ab472c4bcd3aa.jpeg?from=2064092626', NULL, '重庆', 1780985354166, 1780985354164, 7649160297488073514, 7648947265968639247, 'Al时代，苦了这一届的孩子们，咋把老师也换成A1呀', 1780958918, '2', '0', '41', '');
