INSERT INTO `douyin_aweme_comment` VALUES (695, '3985046657832711', 'MS4wLjABAAAAtlJKMdEmU_Z1Xa1qF00o_NRJ8KJOzbWRz5ylYES1R1Bayi_jC5pTWmPyBbGPEK9Y', '73849542832', '73849542832', '理智宝', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_99cde377714b8e2e61109edeab7296da.jpeg?from=2064092626', NULL, '广西', 1780985436375, 1780985436372, 7648223613989094144, 7648148494380780840, '6年了[流泪]', 1780740828, '0', '0', '14', '');
INSERT INTO `douyin_aweme_comment` VALUES (696, '3460906125633997', 'MS4wLjABAAAA3Wyk7MOKuLKG_93uqTBEz1wfGWQJkxDJkbK4ZurGs8KnlFexmJFBrpDRy0Rurjl1', '85382286124', '85382286124', '魏希希學AI', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_31dbaee2de490a50b2ca6200be1f92a7.jpeg?from=2064092626', NULL, '广东', 1780985436388, 1780985436383, 7648220495977399089, 7648148494380780840, '当年高考咬牙闯关，如今刷视频给后辈打气，朱老师横跨多年，年年在线为考生送祝福[笑哭][笑哭][笑哭]', 1780740102, '0', '0', '22', '');
INSERT INTO `douyin_aweme_comment` VALUES (697, '96467831996', 'MS4wLjABAAAASOMFCJFABvVwf0dOqhqBIo-Xd8d4aLtIfLekD59qQJI', '1540916329', '', '赵哥哥', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oMnAeHQ6cE5IAAF93EPQp7iAA6A3wffHOXCDEa.jpeg?from=2064092626', NULL, '湖南', 1780985442110, 1780985442107, 7649273683886392113, 7648939065064115465, '国家的意图很明确，高考生要有真才实学，以前的高中生，就是为了高考而学习，其实学不到真实的知识[呲牙][呲牙][呲牙]', 1780985316, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (698, '553752722420271', 'MS4wLjABAAAA_vGdsFUSqoshmb-8yMYNrMCfR1sQEQjnczNxtpicbLU', '3472248968', 'dyj4x72iqtq5', '人矮蹦的高', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_2b85ee6b6df940c18d63bc353dc7f138.jpeg?from=2064092626', NULL, '云南', 1780985442130, 1780985442128, 7649273333174960945, 7648939065064115465, '不是，老师，我09年数学140，我最后一个大题最后两小问看都没看。我觉得不是奔着top10,完全没必要啊，选择最后一道题，大题最后两问我不要分，不影响我上135啊，能上135基本就满足985211的数学分了', 1780985234, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (699, '2739600227575307', 'MS4wLjABAAAAe3C8Wuvveqx6wk5XkuxZUnR_tQxgu5TtNg1BN3xB-UDFSn2wWrWwpS2xu3xvj4V3', '3612861294', '20141003LoveU', '老碗', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o0EhEA9AIAAfwQBeApAgEqHmDCF8C3PDtmGIqk.jpeg?from=2064092626', NULL, '陕西', 1780985442152, 1780985442150, 7649257722940850998, 7648939065064115465, '我给你总结一下这次高考的目的，揭开了只筛选，不培养的大幕。只筛选出有灵性的学生，然后上大学继续深造，成为将来有可能解决0到1的人才。其他的学生，老老实实去专科，成为技能型人才，建设国家', 1780981600, '4', '0', '10', '');
INSERT INTO `douyin_aweme_comment` VALUES (700, '2894383082902759', 'MS4wLjABAAAAnanrlQP0clR_lp0RY2yaTKuXUZWtUEq9xXNnTGjs9ZJ5-0HXIfjdF2jKBEF_ofIp', '38222937524', '38222937524', '秦王小余', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '山东', 1780985442161, 1780985442159, 7649037292783158035, 7648939065064115465, '我是初三的学生，我做了做高考最后一题，难度不是很大，但是也不是特别简单（当然我会高中数学）', 1780930670, '3', '0', '14', '');
INSERT INTO `douyin_aweme_comment` VALUES (701, '92523235400', 'MS4wLjABAAAA1TzkPBGVix7NHVWXTu1Qk0nwZO6thxo9YS6d3G19544', '336782448', '', '贫僧也用飘柔', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_8e44001306bbf6556924.jpeg?from=2064092626', NULL, '陕西', 1780985442169, 1780985442167, 7649273900258460465, 7648939065064115465, '教育的本质是选拔！一个出题组是多少人研究的成果，不是一两个说的算，他要和国家民族进步与时俱进的，纠结这个没用。', 1780985367, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (702, '95287225410', 'MS4wLjABAAAADAJbX58_i9VGc6ogxjQBwfvl2SczgqvpnjzzXEs5SX0', '2258816456', 'dyn7bm050u24', '编号476578', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_20ad100053e79a965953b.jpeg?from=2064092626', NULL, '江苏', 1780985442186, 1780985442184, 7649264995273327417, 7648939065064115465, '[摊手][摊手][摊手]其实我个人感觉就是跨度太大脱离实际！培养模式根本上就有问题还指望它能培养出自己希望的人才！不过也好……很多家长可以放弃补课了，不行就给孩子多存点钱未来应急吧[捂脸][捂脸][捂脸]', 1780983293, '2', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (703, '1706095267021783', 'MS4wLjABAAAAMLvDdJhQP2UvaJKJzFqks9Fk4GRUCHjrIYncZ1WiC-UkOUgVJjk6VKPH5Gu3bSJ0', '4109459702', 'dyz2porej6xj', '叫啥名呢', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_55f790a234ed4deeb819298349f18631.jpeg?from=2064092626', NULL, '湖北', 1780985442211, 1780985442209, 7649172209270309659, 7648939065064115465, '那种无效刻苦其实才是懒惰，因为他们只需要不断的重复刷题，就可以逃避现实，哪怕一直不思考也可以用我已经很努力了自我麻痹。不断重复已经会的，不会的永远不会，永远不敢面对自己不会的，不敢搭建知识网络，不敢顺应时代，就被时代淘汰', 1780961691, '4', '0', '8', '');
INSERT INTO `douyin_aweme_comment` VALUES (704, '3281372699430301', 'MS4wLjABAAAA7GZ02pT2DwRs0W12TfIBqZeLDjP17HKhTagt_pW6qU28Kqln4S4r_9dfqbpaB3vN', '33372715929', '33372715929', '🈶2️⃣小胖鸭', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_a1bf0fcb85d939d7eb8d081b2ca8a2ac.jpeg?from=2064092626', NULL, '河北', 1780985442228, 1780985442226, 7649073998432977707, 7648939065064115465, '国家需要理科人才 ！国防、芯片必须迅速发展，才能不被敌人掐脖子，不被置于死地。这就要求数学必须优中选优，选拔出天才，保护国家。老百姓家庭考高分上学为自己挣钱，国家需要天才为老百姓活命，哪个更重要一目了然。所以不要仇视数学，在自己能力范围里，尽力走好就行。', 1780938824, '1', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (705, '64379984957', 'MS4wLjABAAAAtkCTjqpKFRJ2f38HaZTigL1LoGy-HJ7f0xSclf4H_mE', '146380052', '', '但许星辰月', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_o0fpDI9BAeDLOYpEyBFMuIAlEWAZQwChAgAn3A.jpeg?from=2064092626', NULL, '河北', 1780985442253, 1780985442251, 7649014372828365577, 7648939065064115465, '当年高考数学120，现在工资6000', 1780925220, '310', '0', '809', '');
INSERT INTO `douyin_aweme_comment` VALUES (706, '852823465794813', 'MS4wLjABAAAAYFdA-jjxOsyDqEEfjX8LkPIQaYBlBToRtIKiYKZNIaw', '3510753597', 'dyiy4qi23ukg', '百鸟朝凤', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '广东', 1780985442261, 1780985442260, 7649013912206590772, 7648939065064115465, '现在初中、高中，90%的老师水平都很低，不会教学，天天题海战术，天天布置天量作业，学生疲于奔命，根本没时间深度研究基础知识，深度思考，一点创性能力都没有，但凡数学、物理成绩很好的，大多数都是靠自学，根本不听老师的。如果认认真真老老实实跟着老师3年，高考肯定完蛋。\n除了国别顶级学校比较好的老师外。', 1780924833, '7', '0', '30', '');
INSERT INTO `douyin_aweme_comment` VALUES (707, '51567973018', 'MS4wLjABAAAAaczTb6ZjQcqPf-CadZt_za8_7dJxech-2Q-ZKvU6wis', '66659959', '', '数学扛把子', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_5c29ef5f26454636b8077079f3451b96.jpeg?from=2064092626', NULL, '广东', 1780985442268, 1780985442267, 7649181787189052211, 7648939065064115465, '其实就是考天赋，考智商，做为老师我还是觉得不公平[捂脸]，因为那些天赋不好的人再怎么努力，再怎么刷题，也弥补不了智商差距，他们没有错，但他们永远考不过智商高的人[捂脸]', 1780963920, '2', '0', '7', '');
INSERT INTO `douyin_aweme_comment` VALUES (708, '3671966870676195', 'MS4wLjABAAAAq-l2zmjGKNUKgSmoh1ZG63narrWNuYYM9yLlDuK0sJyWzQD60i1biiH2b7f5hkDN', '2340204808', 'dys1co4agsbk', 'zp', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '江苏', 1780985442275, 1780985442274, 7649181350033507131, 7648939065064115465, '因为你是学霸，所以你说数学感觉，知道吗？感觉这种东西不是什么人都有的，有些人人穷极一生都追求不来的，无论他多努力，我就是其一，没有任何数学天赋，却学的比谁都认真，从99年上初一开始家里给我请数学家教，每周3次，一直到到05年高考结束，花费无数金钱，可我高考数学却考了56分，而我的文科从来不怎么学，也不刷题，看看就能会，当年我地理142，政治139，语文137，英语116，就唯独数学真学不会[捂脸][捂脸]', 1780963818, '10', '0', '13', '');
INSERT INTO `douyin_aweme_comment` VALUES (709, '4503211337330924', 'MS4wLjABAAAA8eIfKAHWAQy8AibGBrEy-nn8vcEhdAZPGm6eyXlRfavFT6VB7jOJo33jc1vyFrg7', '3841216194', 'dyzx1y3tedu1', '猫拜仙', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '北京', 1780985442287, 1780985442285, 7649161919035278139, 7648939065064115465, '其实北京上海的试卷，很多年前，在我还上学那会就已经是这个趋势了。\n多少年前老师就在讲：计算只是工具，不是目的。一套好的试卷一定是让你刷题战术没用的', 1780959295, '1', '0', '4', '');
