INSERT INTO `douyin_aweme_comment` VALUES (926, '67363417197', 'MS4wLjABAAAASfO-gDdlU1zILJRRomf42V0AYmWB-oJieiVzHJAGsTI', '1363049984', '', '宽容是一种美德', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_b873ddc483024242b10ddbd86596a9e5.jpeg?from=2064092626', NULL, '陕西', 1780985543220, 1780985543218, 7649269246812390190, 7649230936475629222, '这球大头也推着凯儿腰，怎么说。\n已经跳起来的投篮，无球犯规和投篮无关。\n如果这算犯规在前，那么防守者是不是可以在进攻者跳起来投篮的时候将进攻者拽下来，然后判犯规在先，边界球。', 1780984283, '0', '0', '0', '');
