INSERT INTO `douyin_aweme_comment` VALUES (968, '103613541447', 'MS4wLjABAAAAyt81vGOyq_8LKKnyYgy9pQd6WYIE05neI_hVmFkdd1c', '3565018587', 'dy9uvdbgu6mv', 'KKKK', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '浙江', 1780985562923, 1780985562915, 7649269298687640358, 7649246032487796003, '有一说一，你给文班的防守基本都是夹，拉，当然马刺的对于无球防守也不会干净，但单防大头的时候，我觉得就是总决赛的规格，给身体对抗，是身体对抗，卡丝尔，福克斯，哈伯就是这么做的！所以你们被吹更多犯规没什么好说的！', 1780984296, '0', '0', '3', '');
