INSERT INTO `douyin_aweme_comment` VALUES (990, '2906732102947112', 'MS4wLjABAAAAecpmY0ywKDy_KmxLkTv_3MQ9JKMjZOZiqO7A9SDuPpt6JJbLabNIi3k0DjfGNQSQ', '3587856540', 'dy16a18enjup', '江上清风', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oQDCEA9AEAAbFIDoAkAg2esMDCeBvk6nJx4QCd.jpeg?from=2064092626', NULL, '安徽', 1780985568903, 1780985598002, 7649247033706726181, 7649210031275052294, '杨毅你今天是买球了吗，全场看完你解说太不专业了，情绪倾向太明显，这不是专业评论员该做的，而且还是总决赛现场解说，不信大家去看看回放，太不专业，我申明我哪队球迷都不是，纯观后感受', 1780979111, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (991, '97528523094', 'MS4wLjABAAAAf3QHTXoF8GPnOP79uofvglzKoO6stpdafSnccRSGQgY', '867940536', '', '玩玩玩玩玩玩玩', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oYefytXABAEIAsAddXGfGNIE5EAiZl7oSLlBD5.jpeg?from=2064092626', NULL, '广东', 1780985568916, 1780985598014, 7649246102730326842, 7649210031275052294, '没事，尼克斯输了就是放水，赢了就是锋线太好了，攻守兼备，无短板[捂脸]', 1780978894, '4', '0', '18', '');
INSERT INTO `douyin_aweme_comment` VALUES (992, '111292074064', 'MS4wLjABAAAA-FiXpA_NADEMDrwMgpkqQNf5tJwZojZq6eKQeLFKPd8', '2078278360', '', '汉', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_1ca2c000595cb50a8eecb.jpeg?from=2064092626', NULL, '湖南', 1780985568935, 1780985598024, 7649266755591750449, 7649210031275052294, '这么贵的票，看一场球抵得上普通农民一年的收入……有人说狗的命比人都尊贵，我不信，现在我信了…', 1780983702, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (993, '3554058170809732', 'MS4wLjABAAAALakBOaSxMNpwd9YDXy1zItDbAeBsI7KjjLKTPgaFNOG9aBOcgQ9myoE8MwryN9Gb', '4166123909', 'hugebadao666', '陨石是谁的', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_d6b5d6b34a664748894f7b4c917e6355.jpeg?from=2064092626', NULL, '山东', 1780985568946, 1780985598036, 7649271933598925574, 7649210031275052294, '你看文班，来了一趟少林寺。学了铁砂掌和铁肘功，还收了多少大儿子，建议nba的以后都来少林寺进修。', 1780984909, '0', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (994, '1754474137265864', 'MS4wLjABAAAAZJLOAVix_n60ryzrjy9_Gh6icDrcFTVyV620M0T58eOXZDyu266jemNUaHfhnQB8', '3033256704', 'dy13984lqia7', '随风狂飙', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oYM1TBooIAChkGAA1Asit4hAMEBegAi30GCiHf.jpeg?from=2064092626', NULL, '四川', 1780985568959, 1780985598045, 7649239932821848891, 7649210031275052294, '终于扳回一城，文班回到了舒服的状态，福克斯总体表现一般，但最后关键时刻的中投算是稳住了局面，该说不说，第二场最后时刻不失误拿下比赛，这不就领先了吗[捂脸]小伙子们冲劲儿十足，放下包袱，加油冲，继续支持马刺[赞]', 1780977458, '15', '0', '50', '');
INSERT INTO `douyin_aweme_comment` VALUES (995, '111192732824', 'MS4wLjABAAAAGd74sov69z1fwteLy5Pg2l7XZA4M2jPEFVmsHbKWw1E', '2053001997', 'Lb612525Lb', '攀岩', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ogD421d9UE87ATnAiokgRfB3irfAAC9ADIMaA4.jpeg?from=2064092626', NULL, '陕西', 1780985568970, 1780985598057, 7649259143509787441, 7649210031275052294, '门票这么贵都应该感谢詹姆斯，如果是詹姆斯进总决赛，门票价格肯定没这么高。', 1780981931, '3', '0', '12', '');
INSERT INTO `douyin_aweme_comment` VALUES (996, '52704698706', 'MS4wLjABAAAArZ_P84y6-AbGueUSJVfbOAYH38vYVmfnj5JyEFxs4rY', '2054136953', '', '龙卷风', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_c05b43a38cec467eb3542daa2612769f.jpeg?from=2064092626', NULL, '江苏', 1780985568985, 1780985598070, 7649258219110728506, 7649210031275052294, '同志们，分区决赛总决赛央五都有直播，腾讯咪咕收费的话，可以看中央电视台体育频道cctv5', 1780981716, '2', '0', '13', '');
